<title>SIM LIA Gayungsari — V8 Standalone Final</title>
<style>
:root{--blue:#0a6fa5;--blue2:#0d4c70;--navy:#08283e;--orange:#f76522;--orange2:#ff9317;--bg:#f3f6f9;--card:#fff;--text:#173246;--muted:#6c8190;--line:#dbe5ec;--green:#169b72;--red:#dc4d4d;--amber:#e6a023;--purple:#7259c7;--shadow:0 12px 34px rgba(9,40,62,.10)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,Segoe UI,Arial,sans-serif;color:var(--text);background:var(--bg)}button,input,select,textarea{font:inherit}button{cursor:pointer}.hidden{display:none!important}a{color:inherit}.mono{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.muted{color:var(--muted)}
.btn{border:0;border-radius:10px;padding:10px 14px;font-weight:800;display:inline-flex;gap:7px;align-items:center;justify-content:center}.btn-primary{background:var(--orange);color:#fff}.btn-blue{background:var(--blue);color:#fff}.btn-soft{background:#e9f5fb;color:var(--blue)}.btn-outline{background:#fff;border:1px solid #bfd0da;color:var(--blue)}.btn-danger{background:#fff0f0;color:var(--red)}.btn-green{background:#e4f7f0;color:var(--green)}.btn-sm{padding:7px 10px;font-size:12px}.icon-btn{width:32px;height:32px;padding:0;border-radius:8px;border:1px solid var(--line);background:#fff;color:var(--blue);font-weight:900}.icon-btn:hover{background:#eaf6fc}.badge{display:inline-flex;padding:5px 8px;border-radius:999px;font-size:10px;font-weight:900}.b-green{background:#e4f7f0;color:var(--green)}.b-red{background:#ffeded;color:var(--red)}.b-amber{background:#fff5dd;color:#a66a00}.b-blue{background:#e5f3fb;color:var(--blue)}.b-gray{background:#edf2f5;color:#607582}.b-purple{background:#eeeafd;color:var(--purple)}
/* PUBLIC */
#publicSite{background:#fff}.sitebar{height:78px;display:flex;align-items:center;justify-content:space-between;padding:0 5vw;position:sticky;top:0;z-index:60;background:rgba(255,255,255,.97);border-bottom:1px solid var(--line);backdrop-filter:blur(12px)}.brand{display:flex;align-items:center;gap:12px}.brand img{height:58px;width:58px;object-fit:contain}.brand b{color:var(--blue);font-size:20px}.brand small{display:block;color:var(--muted);letter-spacing:.12em;font-size:10px}.nav{display:flex;gap:21px;align-items:center}.nav a{text-decoration:none;font-size:13px;font-weight:850}.hero{min-height:640px;padding:65px 5vw;display:grid;grid-template-columns:1.05fr .95fr;gap:45px;align-items:center;background:linear-gradient(135deg,#eaf8fd 0,#fff 55%,#fff1e7 100%)}.eyebrow{display:inline-flex;background:#dff3fb;color:var(--blue);padding:8px 12px;border-radius:999px;font-size:12px;font-weight:900;letter-spacing:.07em}.hero h1{font-size:clamp(43px,6vw,76px);line-height:.98;letter-spacing:-.045em;margin:18px 0;color:var(--navy)}.hero h1 span{color:var(--orange)}.hero p{max-width:680px;color:#587080;font-size:18px;line-height:1.65}.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}.hero-visual{display:grid;grid-template-columns:1.25fr .75fr;gap:12px}.hero-visual img{width:100%;height:100%;object-fit:cover;border-radius:20px}.hero-main{height:480px;box-shadow:var(--shadow)}.hero-stack{display:grid;gap:12px}.hero-stack img{height:234px;box-shadow:var(--shadow)}.public-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:-38px;padding:0 5vw;position:relative;z-index:10}.public-stat{background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px;box-shadow:var(--shadow)}.public-stat b{display:block;font-size:25px;color:var(--blue)}.public-stat span{font-size:12px;color:var(--muted)}.section{padding:70px 5vw}.section.alt{background:#f4f8fb}.section.dark{background:linear-gradient(145deg,#08283e,#0c5179);color:#fff}.head{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:30px}.head h2{font-size:37px;margin:0;color:var(--navy)}.dark .head h2{color:#fff}.head p{max-width:650px;color:var(--muted);line-height:1.6;margin:0}.dark .head p{color:#c7d8e2}.program-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.program-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 8px 22px rgba(9,40,62,.05);display:flex;flex-direction:column}.program-card .code{font-size:31px;font-weight:950;color:var(--blue)}.program-card h3{margin:4px 0 8px}.program-card p{font-size:13px;color:var(--muted);line-height:1.55}.program-card .meta{margin-top:auto;padding-top:14px;display:flex;justify-content:space-between;font-size:11px;font-weight:850;color:var(--orange)}.feature{display:grid;grid-template-columns:1fr 1fr;gap:35px;align-items:center}.feature img{width:100%;border-radius:22px;box-shadow:var(--shadow)}.feature-list{display:grid;gap:12px}.feature-item{display:flex;gap:12px;background:#fff;border:1px solid var(--line);padding:16px;border-radius:14px}.feature-item i{font-style:normal;width:36px;height:36px;border-radius:10px;background:#e5f5fc;color:var(--blue);display:grid;place-items:center;font-weight:900}.price-box{display:grid;grid-template-columns:.95fr 1.05fr;gap:25px;align-items:center}.price-box img{width:100%;border-radius:20px;box-shadow:var(--shadow)}.content-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.content-card{background:#fff;border:1px solid var(--line);border-radius:17px;overflow:hidden;box-shadow:0 7px 20px rgba(9,40,62,.06)}.content-card img{width:100%;height:190px;object-fit:cover}.content-card .pad{padding:17px}.content-card h3{margin:7px 0}.content-card p{font-size:13px;color:var(--muted);line-height:1.5}.media-strip{display:grid;grid-template-columns:1fr 1fr;gap:18px}.media-card{background:#fff;border:1px solid rgba(255,255,255,.25);border-radius:17px;padding:20px;color:var(--text);display:grid;grid-template-columns:130px 1fr;gap:16px}.media-card img{width:130px;height:105px;object-fit:cover;border-radius:12px}.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.contact-card,.form-card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:25px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:6px}.field.full{grid-column:1/-1}.field label{font-size:12px;font-weight:850}.field input,.field select,.field textarea{border:1px solid #cbd9e2;border-radius:10px;padding:10px 11px;background:#fff;width:100%}.footer{padding:28px 5vw;background:#071e2f;color:#b9ccd7;display:flex;justify-content:space-between;flex-wrap:wrap;gap:20px}
/* ADMIN */
#adminApp{display:none;min-height:100vh}.sidebar{position:fixed;left:0;top:0;bottom:0;width:300px;background:linear-gradient(180deg,#07354f,#071e2f);z-index:80;color:#fff;overflow:auto}.sbrand{height:88px;display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid rgba(255,255,255,.1)}.sbrand img{width:54px;height:54px;object-fit:contain;background:#fff;border-radius:12px;padding:3px}.sbrand small{color:#9db6c5;display:block}.menu-group-title{padding:16px 18px 7px;color:#7799ad;font-size:10px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.menu-parent,.menu-link{margin:3px 10px;border-radius:10px;color:#d9e7ee}.menu-parent-head,.menu-link{display:flex;align-items:center;gap:10px;padding:11px 13px;font-size:13px;font-weight:780;cursor:pointer}.menu-parent-head:hover,.menu-link:hover,.menu-link.active{background:rgba(255,255,255,.11);color:#fff}.menu-parent-head .arrow{margin-left:auto}.submenu{display:none;padding:0 0 6px 35px}.menu-parent.open .submenu{display:block}.submenu a{display:block;color:#a9c0ce;text-decoration:none;padding:8px 10px;border-radius:8px;font-size:12px;cursor:pointer}.submenu a:hover,.submenu a.active{background:rgba(255,255,255,.1);color:#fff}.amain{margin-left:300px;min-height:100vh}.atop{height:72px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0;z-index:30}.search{width:330px;border:1px solid var(--line);border-radius:11px;padding:10px 13px;background:#f7fafc}.user{display:flex;align-items:center;gap:10px}.avatar{width:38px;height:38px;border-radius:50%;background:linear-gradient(135deg,var(--orange),var(--orange2));color:#fff;display:grid;place-items:center;font-weight:900}.content{padding:24px}.crumb{font-size:12px;color:var(--muted);margin-bottom:7px}.page-title{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:18px}.page-title h1{font-size:27px;margin:0;color:var(--navy)}.title-actions{display:flex;gap:8px;flex-wrap:wrap}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.kpi{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:0 5px 17px rgba(9,40,62,.04)}.kpi span{font-size:12px;color:var(--muted)}.kpi b{font-size:28px;display:block;margin:8px 0}.delta{font-size:11px;color:var(--green)}.grid2{display:grid;grid-template-columns:1.3fr .7fr;gap:16px;margin-top:16px}.grid-equal{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 5px 17px rgba(9,40,62,.04)}.card-head{padding:15px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:10px}.card-head h3{margin:0;font-size:16px}.card-body{padding:18px}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.quick button{padding:15px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--text);font-weight:800}.quick button:hover{border-color:var(--blue);color:var(--blue);transform:translateY(-1px)}.chart{height:220px;display:flex;align-items:end;gap:14px;padding:20px 8px 5px}.bar{flex:1;background:linear-gradient(180deg,var(--orange),#ffb36a);border-radius:8px 8px 2px 2px;min-height:20px;position:relative}.bar small{position:absolute;bottom:-22px;left:50%;transform:translateX(-50%);font-size:10px;color:var(--muted)}.table-tools{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:13px;flex-wrap:wrap}.filters{display:flex;gap:8px;flex-wrap:wrap}.filters input,.filters select{border:1px solid var(--line);border-radius:9px;padding:9px 10px;background:#fff}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px}th,td{padding:12px 11px;border-bottom:1px solid #edf1f4;text-align:left;font-size:12px;vertical-align:top}th{color:#687c8b;font-size:10px;text-transform:uppercase;letter-spacing:.05em;background:#f8fafb}.actions{display:flex;gap:5px;flex-wrap:wrap}.tabs{display:flex;gap:7px;border-bottom:1px solid var(--line);margin-bottom:16px;overflow:auto}.tab{padding:11px 14px;border:0;background:transparent;font-weight:800;color:var(--muted);white-space:nowrap}.tab.active{color:var(--blue);border-bottom:3px solid var(--blue)}.tab-panel{display:none}.tab-panel.active{display:block}.panel-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.module-tile{background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px}.module-tile h3{margin:9px 0 5px}.module-tile p{font-size:12px;color:var(--muted);line-height:1.5}.module-icon{width:42px;height:42px;border-radius:12px;background:#e9f5fb;color:var(--blue);display:grid;place-items:center;font-weight:950}.workflow{display:flex;align-items:center;gap:8px;overflow:auto;padding:4px 0 8px}.workflow .step{min-width:130px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px;text-align:center;font-size:11px;font-weight:850}.workflow .arrow{color:var(--muted)}.database-note{background:#eef9f4;border:1px solid #c5ebdd;color:#176d54;border-radius:12px;padding:13px;font-size:12px}.preview-frame{background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden}.preview-top{background:linear-gradient(135deg,var(--blue),var(--blue2));color:#fff;padding:20px}.portal-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:16px}.portal-box{border:1px solid var(--line);border-radius:13px;padding:14px}.portal-box h4{margin:0 0 6px}.portal-news{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;padding:0 16px 16px}.portal-news article{border:1px solid var(--line);border-radius:12px;overflow:hidden}.portal-news img{width:100%;height:110px;object-fit:cover}.portal-news div{padding:10px}.empty{padding:34px;text-align:center;color:var(--muted)}
/* MODAL/TOAST */
.modal{position:fixed;inset:0;background:rgba(3,20,32,.62);z-index:200;display:none;align-items:center;justify-content:center;padding:20px}.modal.open{display:flex}.modal-box{background:#fff;border-radius:18px;width:min(900px,96vw);max-height:92vh;overflow:auto;box-shadow:0 28px 80px rgba(0,0,0,.28)}.modal-head{padding:16px 20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.modal-head h3{margin:0}.modal-body{padding:20px}.toast{position:fixed;right:22px;bottom:22px;background:#09283e;color:#fff;padding:13px 17px;border-radius:11px;z-index:300;opacity:0;transform:translateY(12px);pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:none}.db-indicator{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--green);font-weight:850}.dot{width:9px;height:9px;border-radius:50%;background:var(--green);box-shadow:0 0 0 4px rgba(22,155,114,.12)}
@media(max-width:1100px){.program-grid{grid-template-columns:repeat(2,1fr)}.kpis{grid-template-columns:repeat(2,1fr)}.panel-grid{grid-template-columns:repeat(2,1fr)}.content-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:850px){.nav a{display:none}.hero,.feature,.price-box,.contact-grid,.grid2,.grid-equal{grid-template-columns:1fr}.hero-visual{grid-template-columns:1fr}.hero-stack{display:none}.public-stats{grid-template-columns:1fr 1fr;margin-top:0;padding-top:16px}.sidebar{width:78px}.sidebar .txt,.menu-group-title,.submenu,.arrow{display:none}.menu-parent.open .submenu{display:none}.sbrand div{display:none}.amain{margin-left:78px}.search{width:170px}.program-grid,.kpis,.panel-grid,.quick,.content-grid,.portal-grid,.portal-news,.media-strip{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.content{padding:16px}.media-card{grid-template-columns:90px 1fr}.media-card img{width:90px;height:90px}}

.profile-shell{display:grid;grid-template-columns:250px 1fr;gap:18px}.profile-aside{background:linear-gradient(160deg,var(--blue2),var(--navy));color:#fff;border-radius:18px;padding:20px;text-align:center}.profile-avatar{width:104px;height:104px;border-radius:50%;margin:0 auto 12px;display:grid;place-items:center;background:#fff;color:var(--blue);font-size:38px;font-weight:900;border:5px solid rgba(255,255,255,.25);overflow:hidden}.profile-avatar img{width:100%;height:100%;object-fit:cover}.profile-aside h3{margin:6px 0}.profile-aside .badge{margin:4px}.profile-nav{display:grid;gap:7px;margin-top:18px;text-align:left}.profile-nav button{border:0;background:rgba(255,255,255,.09);color:#fff;padding:10px 12px;border-radius:9px;text-align:left;font-weight:700}.profile-nav button.active{background:#fff;color:var(--blue2)}.detail-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 22px}.detail-item{padding:10px 0;border-bottom:1px solid var(--line)}.detail-item span{display:block;color:var(--muted);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.03em}.detail-item b{display:block;margin-top:4px}.section-title{font-size:15px;font-weight:900;margin:18px 0 8px;color:var(--blue2);border-left:4px solid var(--orange);padding-left:9px}.mini-stat{padding:13px;border:1px solid var(--line);border-radius:12px;background:#fff}.mini-stat b{font-size:21px;display:block;margin-top:3px}.photo-cell{display:flex;align-items:center;gap:10px}.mini-avatar{width:42px;height:42px;border-radius:50%;background:#e7f2f8;color:var(--blue);display:grid;place-items:center;font-weight:900;overflow:hidden}.mini-avatar img{width:100%;height:100%;object-fit:cover}.progress{height:8px;background:#e9eff3;border-radius:10px;overflow:hidden}.progress>i{height:100%;display:block;background:var(--green)}.subtle-box{padding:12px;border-radius:12px;background:#f7fafc;border:1px solid var(--line)}
@media(max-width:900px){.profile-shell{grid-template-columns:1fr}.detail-grid{grid-template-columns:1fr}.profile-nav{grid-template-columns:repeat(2,1fr)}}

.version-pill{display:inline-flex;align-items:center;padding:4px 8px;border-radius:999px;background:rgba(255,255,255,.12);color:#d7edf8;font-size:9px;font-weight:900;letter-spacing:.08em;margin-top:5px}
.storage-note{background:#eef9f4;border:1px solid #c5ebdd;color:#176d54;border-radius:12px;padding:13px;font-size:12px;display:flex;gap:9px;align-items:flex-start}
.storage-note b{color:#0b6048}.action-wrap{display:flex;gap:5px;flex-wrap:wrap;min-width:190px}.file-drop{border:1px dashed #a9c5d5;background:#f7fbfd;border-radius:12px;padding:16px;text-align:center}.metric-note{font-size:11px;color:var(--muted);margin-top:3px}.empty-action{padding:24px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:12px}.activity{display:grid;gap:10px}.activity>div{padding:12px;border:1px solid var(--line);border-radius:12px}.activity span{display:block;color:var(--muted);font-size:11px;margin-top:3px}.chart-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.legend{display:flex;gap:10px;flex-wrap:wrap;font-size:10px;color:var(--muted)}.legend span{display:flex;align-items:center;gap:5px}.legend i{width:8px;height:8px;border-radius:50%;display:inline-block}.progress-row{display:grid;grid-template-columns:minmax(160px,1fr) 1fr 55px;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid #edf1f4}.progress-track{height:9px;background:#e8eef2;border-radius:999px;overflow:hidden}.progress-fill{height:100%;background:linear-gradient(90deg,var(--blue),var(--orange));border-radius:999px}.ledger-positive{color:var(--green);font-weight:800}.ledger-negative{color:var(--red);font-weight:800}
@media(max-width:700px){.progress-row{grid-template-columns:1fr}.action-wrap{min-width:150px}}
