function uid(prefix='id'){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}
function money(n){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n||0))}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function badge(v){let s=String(v||'');let c=/lunas|aktif|terbit|posted|terverifikasi|disetujui|hadir/i.test(s)?'b-green':/belum|menunggu|sebagian|draft|persiapan/i.test(s)?'b-amber':/postponed|batal|ditolak|tidak/i.test(s)?'b-red':'b-blue';return `<span class="badge ${c}">${esc(s)}</span>`}
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function openModal(title,html){modalTitle.textContent=title;modalBody.innerHTML=html;modal.classList.add('open')}function closeModal(){modal.classList.remove('open')}
function openDB(){return new Promise((resolve,reject)=>{let req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=e=>{let d=e.target.result;STORES.forEach(s=>{if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:'id'})})};req.onsuccess=e=>resolve(e.target.result);req.onerror=e=>reject(e.target.error)})}
function tx(store,mode='readonly'){return db.transaction(store,mode).objectStore(store)}
function all(store){return new Promise((resolve,reject)=>{let r=tx(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function put(store,obj){return new Promise((resolve,reject)=>{let r=tx(store,'readwrite').put(obj);r.onsuccess=()=>resolve(obj);r.onerror=()=>reject(r.error)})}
function del(store,id){return new Promise((resolve,reject)=>{let r=tx(store,'readwrite').delete(id);r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function loadState(){for(const s of STORES)state[s]=await all(s)}
async function seedIfNeeded(){let count=await new Promise((resolve,reject)=>{let r=tx('settings').count();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(count)return;for(const [store,items] of Object.entries(SEED)){for(const item of items)await put(store,item)} }
async function save(store,obj,action='Simpan'){await put(store,obj);await put('audit',{id:uid('aud'),time:new Date().toISOString(),action,store,entityId:obj.id,user:'Administrator'});await loadState();renderCurrent();renderPublic();toast(action+' berhasil')}
async function removeItem(store,id){if(!confirm('Hapus data ini? Riwayat demo akan tercatat di audit.'))return;await del(store,id);await put('audit',{id:uid('aud'),time:new Date().toISOString(),action:'Hapus',store,entityId:id,user:'Administrator'});await loadState();renderCurrent();renderPublic();toast('Data dihapus')}
function renderMenu(){sidebarMenu.innerHTML=menu.map(g=>`<div class="menu-group-title">${g.group}</div>${g.items.map(it=>it.children?`<div class="menu-parent"><div class="menu-parent-head"><span>${it.icon}</span><span class="txt">${it.label}</span><span class="arrow">⌄</span></div><div class="submenu">${it.children.map(c=>`<a data-route="${c[0]}">${c[1]}</a>`).join('')}</div></div>`:`<div class="menu-link" data-route="${it.id}"><span>${it.icon}</span><span class="txt">${it.label}</span></div>`).join('')}`).join('');document.querySelectorAll('.menu-parent-head').forEach(x=>x.onclick=()=>x.parentElement.classList.toggle('open'));document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>go(x.dataset.route))}
function page(title,subtitle,actions,body){return `<div class="crumb">SIM LIA Gayungsari / ${esc(title)}</div><div class="page-title"><div><h1>${esc(title)}</h1><div class="muted" style="font-size:12px">${subtitle||''}</div></div><div class="title-actions">${actions||''}</div></div>${body}`}
function card(title,body,actions=''){return `<section class="card"><div class="card-head"><h3>${title}</h3>${actions}</div><div class="card-body">${body}</div></section>`}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">Belum ada data.</td></tr>`}</tbody></table></div>`}
function actionButtons(store,id,editFn,extra=''){return `<div class="actions">${extra}<button class="icon-btn" title="Edit" onclick="${editFn}('${id}')">✎</button><button class="icon-btn" title="Hapus" onclick="removeItem('${store}','${id}')">×</button></div>`}
function org(){return state.settings.find(x=>x.id==='org')||{}}
function appSetting(){return state.settings.find(x=>x.id==='app')||{}}
function openAdmin(){publicSite.style.display='none';adminApp.style.display='block';window.scrollTo(0,0);go('dashboard')}function backToPublic(){adminApp.style.display='none';publicSite.style.display='block';renderPublic();window.scrollTo(0,0)}
function go(route){currentRoute=route;document.querySelectorAll('[data-route]').forEach(x=>x.classList.toggle('active',x.dataset.route===route));let active=document.querySelector(`[data-route="${route}"]`);if(active?.closest('.menu-parent'))active.closest('.menu-parent').classList.add('open');renderCurrent();window.scrollTo(0,0)}
function renderCurrent(){const fn=routes[currentRoute]||routes.dashboard;pageHost.innerHTML=fn();bindTabs()}
function bindTabs(){document.querySelectorAll('[data-tabs]').forEach(t=>t.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{let root=b.closest('[data-tabs-root]')||t.parentElement;t.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');root.querySelectorAll('.tab-panel').forEach(x=>x.classList.toggle('active',x.dataset.panel===b.dataset.tab))}))}
function renderPublic(){let o=org();publicLogo.src=o.logo||'/assets/images/logo.png';publicOrgName.textContent=o.name||'LIA Gayungsari';publicTagline.textContent=o.tagline||'';publicContact.innerHTML=`<b>WhatsApp:</b> ${esc(o.phone)}<br><b>Instagram:</b> ${esc(o.instagram)}<br><b>Email:</b> ${esc(o.email)}<br><b>Alamat:</b> ${esc(o.address)}`;footerContact.textContent=`${o.phone} • ${o.instagram} • ${o.address}`;publicPrograms.innerHTML=state.programs.filter(x=>x.active!==false).map(x=>`<article class="program-card"><div class="code">${esc(x.code)}</div><h3>${esc(x.name)}</h3><p><b>${esc(x.segment)}</b></p><p>${esc(x.focus)}</p><span class="badge b-blue">${esc(x.method)}</span><div class="meta"><span>${esc(x.duration)}</span><span>${money(x.fee)}</span></div></article>`).join('');pubProgram.innerHTML=state.programs.map(x=>`<option>${esc(x.code)} — ${esc(x.name)}</option>`).join('');publicFeeList.innerHTML=state.programs.slice(0,5).map(x=>`<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line)"><b>${esc(x.code)}</b><span>${money(x.fee)}</span></div>`).join('');let news=state.content.filter(x=>x.public&&['Berita','Kegiatan'].includes(x.type)&&x.status==='Terbit');publicNews.innerHTML=news.map(contentCard).join('')||'<div class="empty">Belum ada berita.</div>';let media=state.content.filter(x=>x.public&&['Galeri','Instagram','YouTube'].includes(x.type)&&x.status==='Terbit');publicMedia.innerHTML=media.map(x=>`<article class="media-card"><img src="${x.image||'/assets/images/hero-main.jpg'}"><div><span class="badge b-amber">${esc(x.type)}</span><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p>${x.url?`<a class="btn btn-outline btn-sm" target="_blank" href="${esc(x.url)}">Buka ${esc(x.platform||x.type)}</a>`:''}</div></article>`).join('')||'<div class="empty">Belum ada media.</div>'}
function contentCard(x){return `<article class="content-card"><img src="${x.image||'/assets/images/hero-main.jpg'}"><div class="pad"><span class="badge b-blue">${esc(x.type)}</span><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><small class="muted">${esc(x.date)}</small></div></article>`}
async function submitPublicLead(e){e.preventDefault();let lead={id:uid('lead'),name:pubName.value,phone:pubPhone.value,program:pubProgram.value.split(' — ')[0],source:pubSource.value,stage:'Baru',created:new Date().toISOString().slice(0,10),note:pubNote.value};await put('leads',lead);await loadState();e.target.reset();toast('Minat pendaftaran tersimpan di CRM')}
function globalSearch(e){if(e.key!=='Enter')return;let q=e.target.value.toLowerCase();let student=state.students.find(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(q)));if(student){go('students');setTimeout(()=>openStudentDetail(student.id),100);return}let inv=state.invoices.find(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(q)));if(inv){go('invoices');toast('Invoice ditemukan: '+inv.invoiceNo);return}let cls=state.classes.find(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(q)));if(cls){go('classes');setTimeout(()=>openClassDetail(cls.id),100);return}toast('Data tidak ditemukan')}

const routes={
 dashboard:()=>{let activeStudents=state.students.filter(x=>x.status==='Aktif').length,activeClasses=state.classes.filter(x=>x.status==='Aktif').length,receivable=state.invoices.reduce((a,x)=>a+Number(x.balance||0),0),income=state.payments.reduce((a,x)=>a+Number(x.amount||0),0),expense=state.expenses.reduce((a,x)=>a+Number(x.amount||0),0);return page('Dashboard','Ringkasan operasional, akademik, publikasi, dan keuangan.',`<button class="btn btn-outline" onclick="exportDatabase()">Ekspor Database</button><button class="btn btn-primary" onclick="openLeadForm()">＋ Calon Siswa</button>`,`<div class="database-note">Penyimpanan lokal browser <b>localStorage</b> aktif. Data tambah/edit/hapus tersimpan setelah halaman ditutup. Backup JSON dapat diekspor dari menu Pengaturan.</div><div class="kpis" style="margin-top:15px"><div class="kpi"><span>Siswa Aktif</span><b>${activeStudents}</b><small class="delta">${state.students.length} total profil</small></div><div class="kpi"><span>Kelas Aktif</span><b>${activeClasses}</b><small class="delta">${state.enrollments.length} enrollment</small></div><div class="kpi"><span>Calon Siswa</span><b>${state.leads.length}</b><small class="delta">${state.placements.filter(x=>/Menunggu/.test(x.status)).length} placement menunggu</small></div><div class="kpi"><span>Piutang</span><b>${money(receivable)}</b><small class="delta">Perlu tindak lanjut</small></div></div><div class="grid2"><div>${card('Tindakan Cepat',`<div class="quick"><button onclick="openStudentForm()">＋ Tambah Murid</button><button onclick="openClassForm()">＋ Buat Kelas</button><button onclick="openInvoiceForm()">＋ Buat Invoice</button><button onclick="openContentForm()">＋ Publikasi</button></div>`)}<div style="margin-top:16px">${card('Alur Penerimaan Siswa',`<div class="workflow"><div class="step">Calon Siswa</div><span class="arrow">→</span><div class="step">Registrasi</div><span class="arrow">→</span><div class="step">Placement</div><span class="arrow">→</span><div class="step">Persetujuan Level</div><span class="arrow">→</span><div class="step">Murid + Invoice</div><span class="arrow">→</span><div class="step">Enrollment Kelas</div></div>`)}</div></div><div>${card('Keuangan Bulan Berjalan',`<div style="display:grid;gap:12px"><div><span class="muted">Penerimaan</span><h2 style="margin:4px 0;color:var(--green)">${money(income)}</h2></div><div><span class="muted">Pengeluaran</span><h2 style="margin:4px 0;color:var(--red)">${money(expense)}</h2></div><div><span class="muted">Surplus sederhana</span><h2 style="margin:4px 0;color:var(--blue)">${money(income-expense)}</h2></div></div>`)}<div style="margin-top:16px">${card('Publikasi Terbit',`<div style="font-size:34px;font-weight:900;color:var(--orange)">${state.content.filter(x=>x.status==='Terbit').length}</div><p class="muted">Berita, kegiatan, galeri, Instagram, dan YouTube yang tampil pada frontend/portal.</p><button class="btn btn-soft" onclick="go('news-events')">Kelola Publikasi</button>`)}</div></div></div>`)} ,
 'org-profile':()=>orgProfilePage(),facilities:()=>entityTablePage('Fasilitas & Ruang','Data ruang mengadopsi pola daftar fasilitas pada screen capture: kategori, lokasi, kondisi, kapasitas, status, pencarian, dan aksi.','facilities',[['name','Nama Ruang'],['category','Kategori'],['location','Lokasi'],['capacity','Kapasitas'],['condition','Kondisi'],['status','Status']],openFacilityForm),
 'achievement-gallery':()=>achievementGalleryPage(),'news-events':()=>contentManagerPage(['Berita','Kegiatan']),'social-media':()=>contentManagerPage(['Instagram','YouTube']),'signature':()=>signaturePage(),
 programs:()=>entityTablePage('Program & Level','Master program mengambil struktur GEYL, GET, GEA, CVS, CVB, TOEFL, dan IELTS dari dokumen awal.','programs',[['code','Kode'],['name','Program'],['segment','Sasaran'],['levels','Level'],['duration','Durasi'],['fee','Biaya']],openProgramForm,true),
 periods:()=>entityTablePage('Periode, Kalender & Slot','Periode belajar, tanggal aktif, hari libur, serta slot jadwal.','periods',[['code','Kode'],['name','Nama Periode'],['start','Mulai'],['end','Selesai'],['status','Status']],openPeriodForm),
 'grading-master':()=>gradingMasterPage(),employees:()=>entityTablePage('Daftar Pegawai','Identitas, status kerja, jabatan, kompetensi program, kontak, dan status aktif.','employees',[['name','Nama'],['role','Jabatan'],['employment','Status Kerja'],['programs','Kompetensi'],['phone','Kontak'],['status','Status']],openEmployeeForm),
 'teacher-assignment':()=>teacherAssignmentPage(),'teaching-summary':()=>teachingSummaryPage(),crm:()=>crmPage(),placement:()=>placementPage(),waiting:()=>waitingPage(),students:()=>studentsPage(),'student-lifecycle':()=>studentLifecyclePage(),classes:()=>classesPage(),schedules:()=>schedulesPage(),attendance:()=>attendancePage(),materials:()=>materialsPage(),assignments:()=>assignmentsPage(),grading:()=>gradingPage(),'reports-certs':()=>reportsCertsPage(),'finance-dashboard':()=>financeDashboardPage(),invoices:()=>invoicesPage(),'payments-receivables':()=>paymentsReceivablesPage(),discounts:()=>discountsPage(),expenses:()=>expensesPage(),'cash-bank':()=>cashBankPage(),accounting:()=>accountingPage(),closing:()=>closingPage(),letters:()=>lettersPage(),announcements:()=>announcementsPage(),reports:()=>reportsPage(),'portal-content':()=>portalContentPage(),'portal-preview':()=>portalPreviewPage(),users:()=>entityTablePage('Pengguna & Hak Akses','Akun, peran, status, dan cakupan akses sistem.','users',[['name','Nama'],['email','Email'],['role','Peran'],['status','Status']],openUserForm),settings:()=>settingsPage()
};
function entityTablePage(title,subtitle,store,cols,formFn,fee=false){let rows=state[store].map(x=>`<tr>${cols.map(c=>`<td>${c[0]==='status'?badge(x[c[0]]):c[0]==='fee'?money(x[c[0]]):esc(x[c[0]])}</td>`).join('')}<td>${actionButtons(store,x.id,formFn.name)}</td></tr>`);return page(title,subtitle,`<button class="btn btn-primary" onclick="${formFn.name}()">＋ Tambah</button>`,card(title,`<div class="table-tools"><div class="filters"><input placeholder="Cari data" oninput="filterTable(this)"></div><button class="btn btn-outline btn-sm" onclick="exportStoreCSV('${store}')">Ekspor CSV</button></div>${table([...cols.map(c=>c[1]),'Aksi'],rows)}`))}
function filterTable(inp){let q=inp.value.toLowerCase(),trs=inp.closest('.card-body').querySelectorAll('tbody tr');trs.forEach(tr=>tr.style.display=tr.textContent.toLowerCase().includes(q)?'':'none')}
function orgProfilePage(){let o=org();return page('Profil Lembaga','Identitas lembaga, alamat, kontak, peta, legalitas, visi/misi, logo, dan rekening.',`<button class="btn btn-primary" onclick="openOrgForm()">Edit Profil</button>`,`<div class="grid2"><div>${card('Identitas Lembaga',`<div class="grid-equal"><div><p><b>Nama</b><br>${esc(o.name)}</p><p><b>Alamat</b><br>${esc(o.address)}</p><p><b>Kontak</b><br>${esc(o.phone)} • ${esc(o.email)}</p><p><b>Media Sosial</b><br>${esc(o.instagram)}</p></div><div><p><b>Tagline</b><br>${esc(o.tagline)}</p><p><b>Visi</b><br>${esc(o.vision)}</p><p><b>Misi</b><br>${esc(o.mission)}</p></div></div>`)}<div style="margin-top:16px">${card('Peta dan Informasi Tambahan',`<div style="height:240px;border-radius:12px;background:linear-gradient(135deg,#dceaf1,#f7fbfd);display:grid;place-items:center;color:var(--muted)">Peta lokasi / koordinat lembaga<br><small>Field dapat diisi pada Edit Profil</small></div>`)}</div></div><div>${card('Logo Lembaga',`<img src="${o.logo}" style="width:100%;max-height:260px;object-fit:contain"><p class="muted">Logo ini digunakan pada frontend, portal, dokumen, dan dashboard.</p>`)}<div style="margin-top:16px">${card('Status Kelengkapan',`<p>${badge('Aktif')} Profil utama</p><p>${badge(o.phone?'Lengkap':'Belum Lengkap')} Kontak</p><p>${badge(o.logo?'Lengkap':'Belum Lengkap')} Logo</p><p>${badge(o.vision?'Lengkap':'Belum Lengkap')} Visi/Misi</p>`)}</div></div></div>`)}
function achievementGalleryPage(){let achRows=state.achievements.map(x=>`<tr><td>${esc(x.year)}</td><td><b>${esc(x.title)}</b></td><td>${esc(x.category)}</td><td>${esc(x.description)}</td><td>${actionButtons('achievements',x.id,'openAchievementForm')}</td></tr>`),gallery=state.content.filter(x=>x.type==='Galeri');return page('Prestasi & Galeri','Prestasi lembaga dan galeri publik dikelola dalam satu menu, tetapi disimpan sebagai entitas berbeda.',`<button class="btn btn-outline" onclick="openAchievementForm()">＋ Prestasi</button><button class="btn btn-primary" onclick="openContentForm(null,'Galeri')">＋ Galeri</button>`,`<div data-tabs-root><div class="tabs" data-tabs><button class="tab active" data-tab="ach">Prestasi</button><button class="tab" data-tab="gal">Galeri</button></div><div class="tab-panel active" data-panel="ach">${card('Daftar Prestasi',table(['Tahun','Judul','Kategori','Deskripsi','Aksi'],achRows))}</div><div class="tab-panel" data-panel="gal">${card('Galeri Terpublikasi',`<div class="content-grid">${gallery.map(x=>`<article class="content-card"><img src="${x.image}"><div class="pad"><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><div class="actions"><button class="btn btn-soft btn-sm" onclick="openContentForm('${x.id}')">Edit</button><button class="btn btn-danger btn-sm" onclick="removeItem('content','${x.id}')">Hapus</button></div></div></article>`).join('')}</div>`)}</div></div>`)}
function contentManagerPage(types){let items=state.content.filter(x=>types.includes(x.type)),rows=items.map(x=>`<tr><td><img src="${x.image||'/assets/images/hero-main.jpg'}" style="width:72px;height:50px;object-fit:cover;border-radius:8px"></td><td><b>${esc(x.title)}</b><br><small>${esc(x.summary)}</small></td><td>${badge(x.type)}</td><td>${esc(x.date)}</td><td>${x.public?badge('Frontend'):''} ${x.portal?badge('Portal'):''}</td><td>${badge(x.status)}</td><td>${actionButtons('content',x.id,'openContentForm')}</td></tr>`);return page(types.join(' & '),'Konten dapat ditargetkan ke frontend publik, portal siswa/orang tua, atau keduanya.',`<button class="btn btn-primary" onclick="openContentForm(null,'${types[0]}')">＋ Tambah Konten</button>`,card('Daftar Konten',`<div class="workflow"><div class="step">Buat Konten</div><span class="arrow">→</span><div class="step">Pilih Target</div><span class="arrow">→</span><div class="step">Terbitkan</div><span class="arrow">→</span><div class="step">Frontend / Portal</div></div>${table(['Media','Konten','Jenis','Tanggal','Target','Status','Aksi'],rows)}`))}
function signaturePage(){return page('TTD & Stempel','Aset tanda tangan dan stempel mengikuti pola screen capture, ditambah versi, masa berlaku, dan pembatasan dokumen.',`<button class="btn btn-primary" onclick="toast('Prototype: dialog unggah TTD/stempel dibuka')">Unggah Aset</button>`,`<div class="grid-equal"><div>${card('TTD + Stempel Pimpinan',`<div style="height:220px;border:2px dashed var(--line);border-radius:13px;display:grid;place-items:center"><div style="text-align:center"><div style="font-size:55px;color:var(--blue)">✍</div><b>Aset Transparan</b><p class="muted">PNG, status valid, versi aktif</p></div></div><p>${badge('Valid')} Berlaku untuk sertifikat, rapor, dan surat.</p>`)}</div><div>${card('Stempel Lembaga',`<div style="height:220px;border:2px dashed var(--line);border-radius:13px;display:grid;place-items:center"><div style="text-align:center"><div style="font-size:55px;color:var(--orange)">◎</div><b>Stempel LIA Gayungsari</b><p class="muted">Background transparan</p></div></div><p>${badge('Valid')} Riwayat pemakaian disimpan per dokumen.</p>`)}</div></div>`)}
function gradingMasterPage(){return page('Komponen & Sistem Nilai','Master bobot, konversi angka-huruf, syarat lulus, promotion test, remedial, dan makeup test.',`<button class="btn btn-primary" onclick="toast('Komponen nilai baru ditambahkan pada prototype')">＋ Komponen</button>`,`<div class="panel-grid"><div class="module-tile"><div class="module-icon">%</div><h3>Komponen Nilai</h3><p>Tugas 20%, kehadiran 10%, speaking 25%, writing 20%, promotion test 25%.</p><button class="btn btn-soft btn-sm">Atur Bobot</button></div><div class="module-tile"><div class="module-icon">A</div><h3>Konversi Nilai</h3><p>A: 85–100, B: 75–84, C: 65–74, Perlu Penguatan: &lt;65.</p><button class="btn btn-soft btn-sm">Atur Konversi</button></div><div class="module-tile"><div class="module-icon">↑</div><h3>Aturan Kenaikan Level</h3><p>Nilai akhir minimum, batas kehadiran, dan keputusan koordinator akademik.</p><button class="btn btn-soft btn-sm">Atur Kelulusan</button></div></div>`)}
function teacherAssignmentPage(){let rows=state.classes.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.program)} ${esc(c.level)}</td><td>${esc(c.teacher)}</td><td>${esc(c.days)} ${esc(c.time)}</td><td>${esc(c.room)}</td><td>${badge('Tidak Bentrok')}</td><td><button class="icon-btn" onclick="openClassForm('${c.id}')">✎</button></td></tr>`);return page('Penugasan & Ketersediaan','Penugasan kelas memeriksa ketersediaan pengajar, ruang, dan bentrok jadwal.',`<button class="btn btn-primary" onclick="openClassForm()">＋ Penugasan Kelas</button>`,card('Penugasan Aktif',table(['Kelas','Program/Level','Pengajar','Jadwal','Ruang','Validasi','Aksi'],rows)))}
function teachingSummaryPage(){let rows=state.employees.filter(x=>x.role==='Pengajar').map(e=>{let cls=state.classes.filter(c=>c.teacher===e.name);return `<tr><td><b>${esc(e.name)}</b></td><td>${cls.length}</td><td>${cls.length*18}</td><td>${cls.length*16}</td><td>${cls.length*2}</td><td>${esc(e.availability)}</td><td><button class="btn btn-soft btn-sm" onclick="toast('Detail rekap mengajar dibuka')">Detail</button></td></tr>`});return page('Rekap Mengajar & Absensi','Ringkasan sesi dijadwalkan, terlaksana, pengganti, batal, serta absensi pengajar.',`<button class="btn btn-outline" onclick="exportStoreCSV('employees')">Ekspor</button>`,card('Teaching Summary',table(['Pengajar','Kelas','Sesi Dijadwalkan','Terlaksana','Sisa','Ketersediaan','Aksi'],rows)))}
function crmPage(){let rows=state.leads.map(x=>`<tr><td>${esc(x.created)}</td><td><b>${esc(x.name)}</b><br>${esc(x.phone)}</td><td>${esc(x.program)}</td><td>${esc(x.source)}</td><td>${badge(x.stage)}</td><td><div class="actions"><button class="btn btn-soft btn-sm" onclick="openLeadForm('${x.id}')">Edit</button><button class="btn btn-blue btn-sm" onclick="schedulePlacement('${x.id}')">Placement</button><button class="btn btn-green btn-sm" onclick="convertLeadToStudent('${x.id}')">Jadi Murid</button></div></td></tr>`);return page('Calon Siswa & Registrasi','Form frontend, Instagram, referral, dan input front office masuk ke tabel calon siswa yang sama.',`<button class="btn btn-primary" onclick="openLeadForm()">＋ Calon Siswa</button>`,`${card('Pipeline Pendaftaran',`<div class="workflow"><div class="step">Baru<br><b>${state.leads.filter(x=>x.stage==='Baru').length}</b></div><span class="arrow">→</span><div class="step">Placement<br><b>${state.leads.filter(x=>/Placement/.test(x.stage)).length}</b></div><span class="arrow">→</span><div class="step">Pembayaran<br><b>${state.leads.filter(x=>/Pembayaran/.test(x.stage)).length}</b></div><span class="arrow">→</span><div class="step">Aktif</div></div>`)}<div style="margin-top:16px">${card('Daftar Calon Siswa',table(['Tanggal','Calon Siswa','Program','Sumber','Tahap','Tindakan'],rows))}</div>`)}
function placementPage(){let rows=state.placements.map(x=>`<tr><td>${esc(x.date)} ${esc(x.time)}</td><td><b>${esc(x.participant)}</b></td><td>${esc(x.room)}</td><td>${esc(x.examiner)}</td><td>${x.score??'-'}</td><td>${esc(x.recommendation||'-')}</td><td>${badge(x.status)}</td><td><div class="actions"><button class="btn btn-soft btn-sm" onclick="openPlacementForm('${x.id}')">Edit Hasil</button>${/Menunggu/.test(x.status)?`<button class="btn btn-green btn-sm" onclick="approvePlacement('${x.id}')">Setujui</button>`:''}</div></td></tr>`);return page('Placement Test','Jadwal, peserta, skor komponen, rekomendasi program/level, persetujuan, dan konversi menjadi murid.',`<button class="btn btn-primary" onclick="openPlacementForm()">＋ Jadwal Placement</button>`,card('Daftar Placement',table(['Jadwal','Peserta','Ruang','Penguji','Skor','Rekomendasi','Status','Aksi'],rows)))}
function waitingPage(){let leads=state.leads.filter(x=>/Menunggu|Placement/.test(x.stage));let inv=state.invoices.filter(x=>x.balance>0);return page('Waiting List','Daftar tunggu kelas, hasil placement, atau pembayaran.',`<button class="btn btn-outline" onclick="go('classes')">Lihat Kapasitas Kelas</button>`,`<div class="grid-equal"><div>${card('Menunggu Proses Akademik',table(['Nama','Program','Tahap'],leads.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.program)}</td><td>${badge(x.stage)}</td></tr>`)))}</div><div>${card('Menunggu Pelunasan',table(['Siswa','Invoice','Saldo'],inv.map(x=>`<tr><td>${esc(x.student)}</td><td>${esc(x.invoiceNo)}</td><td>${money(x.balance)}</td></tr>`)))}</div></div>`)}
function studentsPage(){let rows=state.students.map(x=>{let en=state.enrollments.find(e=>e.studentId===x.id&&e.status==='Aktif'),cl=state.classes.find(c=>c.id===en?.classId),inv=state.invoices.filter(i=>i.studentId===x.id).reduce((a,i)=>a+Number(i.balance),0);return `<tr><td>${esc(x.studentNo)}</td><td><b>${esc(x.name)}</b><br><small>${esc(x.guardianPhone)}</small></td><td>${esc(x.program)}</td><td>${esc(x.level)}</td><td>${esc(cl?.code||'Belum ditempatkan')}</td><td>${badge(x.status)}</td><td>${money(inv)}</td><td><div class="actions"><button class="icon-btn" onclick="openStudentDetail('${x.id}')">👁</button><button class="icon-btn" onclick="openStudentForm('${x.id}')">✎</button><button class="icon-btn" onclick="openInvoiceForm(null,'${x.id}')">Rp</button></div></td></tr>`});return page('Data Murid','Profil 360°: biodata, orang tua/wali, enrollment, kehadiran, nilai, keuangan, komunikasi, dan dokumen.',`<button class="btn btn-primary" onclick="openStudentForm()">＋ Tambah Murid</button>`,card('Daftar Murid',`<div class="table-tools"><div class="filters"><input placeholder="Cari nama/nomor" oninput="filterTable(this)"><select><option>Semua Program</option>${state.programs.map(p=>`<option>${p.code}</option>`).join('')}</select><select><option>Semua Status</option><option>Aktif</option><option>Postponed</option><option>Alumni</option></select></div><button class="btn btn-outline btn-sm" onclick="exportStoreCSV('students')">Ekspor CSV</button></div>${table(['No. Murid','Nama/Kontak Wali','Program','Level','Kelas','Status','Piutang','Aksi'],rows)}`))}
function studentLifecyclePage(){return page('Mutasi, Postponed & Alumni','Satu menu untuk perubahan status siswa agar riwayat tidak terhapus dan mudah ditelusuri.',`<button class="btn btn-primary" onclick="openLifecycleForm()">＋ Pengajuan</button>`,`<div class="panel-grid"><div class="module-tile"><div class="module-icon">⇄</div><h3>Mutasi/Pindah Kelas</h3><p>Memeriksa level, kapasitas, jadwal, dan keuangan sebelum persetujuan.</p><b>${state.audit.filter(x=>x.action==='Pindah Kelas').length} riwayat</b></div><div class="module-tile"><div class="module-icon">Ⅱ</div><h3>Postponed</h3><p>Mencatat tanggal mulai, rencana kembali, sisa sesi/kredit, dan kelas reaktivasi.</p><b>${state.students.filter(x=>x.status==='Postponed').length} siswa</b></div><div class="module-tile"><div class="module-icon">★</div><h3>Alumni</h3><p>Program terakhir, level akhir, sertifikat, dan kebutuhan kursus lanjutan.</p><b>${state.students.filter(x=>x.status==='Alumni').length} alumni</b></div></div>`)}
function classesPage(){let rows=state.classes.map(c=>{let n=state.enrollments.filter(e=>e.classId===c.id&&e.status==='Aktif').length;return `<tr><td><b>${esc(c.code)}</b></td><td>${esc(c.program)} ${esc(c.level)}</td><td>${esc(c.period)}</td><td>${esc(c.teacher)}</td><td>${esc(c.days)}<br>${esc(c.time)}</td><td>${esc(c.room)}</td><td>${n}/${c.capacity}</td><td>${badge(c.status)}</td><td><div class="actions"><button class="icon-btn" onclick="openClassDetail('${c.id}')">👁</button><button class="icon-btn" onclick="openClassForm('${c.id}')">✎</button><button class="icon-btn" onclick="duplicateClass('${c.id}')">⧉</button></div></td></tr>`});return page('Rombel & Anggota','Profil kelas, anggota, pengajar, ruang, kapasitas, duplikasi periode, dan tautan ke absensi/materi/nilai.',`<button class="btn btn-primary" onclick="openClassForm()">＋ Buat Kelas</button>`,card('Daftar Kelas',table(['Kode Kelas','Program/Level','Periode','Pengajar','Jadwal','Ruang','Anggota','Status','Aksi'],rows)))}
function schedulesPage(){let rows=state.classes.map(c=>`<tr><td>${esc(c.days)}</td><td>${esc(c.time)}</td><td><b>${esc(c.code)}</b></td><td>${esc(c.teacher)}</td><td>${esc(c.room)}</td><td>${badge('Tidak Bentrok')}</td><td><button class="btn btn-soft btn-sm" onclick="openClassForm('${c.id}')">Reschedule</button></td></tr>`);return page('Jadwal & Ruang','Monitoring jadwal mendeteksi bentrok pengajar, ruang, dan siswa.',`<button class="btn btn-outline" onclick="go('facilities')">Kelola Ruang</button>`,card('Kalender Mingguan',table(['Hari','Jam','Kelas','Pengajar','Ruang','Validasi','Aksi'],rows)))}
function attendancePage(){let cls=state.classes[0],members=state.enrollments.filter(e=>e.classId===cls?.id).map(e=>state.students.find(s=>s.id===e.studentId)).filter(Boolean);return page('Absensi QR & Manual','Pilih kelas dan tanggal; status kehadiran disimpan per siswa dan sesi.',`<button class="btn btn-primary" onclick="saveAttendanceDemo()">Simpan Absensi</button>`,`<div class="table-tools"><div class="filters"><select id="attClass" onchange="renderCurrent()">${state.classes.map(c=>`<option value="${c.id}">${esc(c.code)}</option>`).join('')}</select><input type="date" id="attDate" value="${new Date().toISOString().slice(0,10)}"></div><span class="badge b-blue">Metode: QR / Manual</span></div>${card('Daftar Kehadiran '+(cls?.code||''),table(['No. Murid','Nama','Status','Metode','Catatan'],members.map(s=>`<tr><td>${esc(s.studentNo)}</td><td>${esc(s.name)}</td><td><select class="att-status" data-student="${s.id}"><option>Hadir</option><option>Izin</option><option>Sakit</option><option>Alpa</option></select></td><td><select class="att-method"><option>QR</option><option>Manual</option></select></td><td><input placeholder="Catatan"></td></tr>`)))}`)}
function materialsPage(){let rows=state.materials.map(x=>{let c=state.classes.find(c=>c.id===x.classId);return `<tr><td><b>${esc(x.title)}</b></td><td>${esc(x.type)}</td><td>${esc(x.program)} ${esc(x.level)}</td><td>${esc(c?.code||'Semua Kelas')}</td><td>${x.published?badge('Portal'):badge('Draft')}</td><td>${actionButtons('materials',x.id,'openMaterialForm')}</td></tr>`});return page('Buku, E-book & Materi','Materi dipetakan ke program, level, kelas, atau sesi dan dapat dipublikasikan ke portal.',`<button class="btn btn-primary" onclick="openMaterialForm()">＋ Materi</button>`,card('Katalog Materi',table(['Judul','Jenis','Program/Level','Kelas','Akses','Aksi'],rows)))}
function assignmentsPage(){let rows=state.assignments.map(x=>{let c=state.classes.find(c=>c.id===x.classId);return `<tr><td><b>${esc(x.title)}</b></td><td>${esc(c?.code)}</td><td>${esc(x.due)}</td><td>${badge(x.status)}</td><td>0 pengumpulan</td><td><div class="actions"><button class="btn btn-soft btn-sm" onclick="toast('Daftar pengumpulan dibuka')">Pengumpulan</button><button class="icon-btn" onclick="openAssignmentForm('${x.id}')">✎</button></div></td></tr>`});return page('Tugas & Pengumpulan','Instruksi, tenggat, lampiran, rubrik, pengumpulan siswa, skor, dan umpan balik.',`<button class="btn btn-primary" onclick="openAssignmentForm()">＋ Tugas</button>`,card('Tugas Kelas',table(['Tugas','Kelas','Tenggat','Status','Pengumpulan','Aksi'],rows)))}
function gradingPage(){let rows=state.scores.map(x=>{let s=state.students.find(s=>s.id===x.studentId),c=state.classes.find(c=>c.id===x.classId);return `<tr><td>${esc(s?.name)}</td><td>${esc(c?.code)}</td><td>${esc(x.component)}</td><td><b>${x.score}</b></td><td>${badge(x.status)}</td><td>${actionButtons('scores',x.id,'openScoreForm')}</td></tr>`});return page('Penilaian & Tes','Input nilai formatif, promotion test, makeup test, konversi nilai, dan persetujuan hasil.',`<button class="btn btn-primary" onclick="openScoreForm()">＋ Input Nilai</button>`,`${card('Nilai Siswa',table(['Siswa','Kelas','Komponen','Skor','Status','Aksi'],rows))}<div style="margin-top:16px"><div class="panel-grid"><div class="module-tile"><div class="module-icon">↑</div><h3>Promotion Test</h3><p>Jadwal, peserta, penguji, skor, rekomendasi naik/mengulang.</p><button class="btn btn-soft btn-sm">Buka</button></div><div class="module-tile"><div class="module-icon">↻</div><h3>Makeup Test</h3><p>Ujian susulan dengan alasan dan persetujuan.</p><button class="btn btn-soft btn-sm">Buka</button></div><div class="module-tile"><div class="module-icon">✓</div><h3>Result Approval</h3><p>Nilai terkunci setelah disetujui koordinator akademik.</p><button class="btn btn-soft btn-sm">Buka</button></div></div></div>`)}
function reportsCertsPage(){let rows=state.students.map(s=>{let scores=state.scores.filter(x=>x.studentId===s.id),avg=scores.length?Math.round(scores.reduce((a,x)=>a+Number(x.score),0)/scores.length):0;return `<tr><td>${esc(s.name)}</td><td>${esc(s.program)} ${esc(s.level)}</td><td>${avg||'-'}</td><td>${avg>=75?badge('Layak Naik Level'):badge('Belum Lengkap')}</td><td><div class="actions"><button class="btn btn-soft btn-sm" onclick="toast('Rapor dipratinjau')">Rapor</button><button class="btn btn-blue btn-sm" onclick="toast('Sertifikat diterbitkan dengan nomor dan QR')">Sertifikat</button></div></td></tr>`});return page('Rapor, DHBS & Sertifikat','Rapor dan sertifikat hanya diterbitkan dari nilai dan kehadiran yang telah diverifikasi.',`<button class="btn btn-outline" onclick="exportStoreCSV('scores')">Ekspor DHBS</button>`,card('Daftar Hasil Belajar',table(['Siswa','Program/Level','Rata-rata','Keputusan','Dokumen'],rows)))}
function financeDashboardPage(){let inc=state.payments.reduce((a,x)=>a+Number(x.amount),0),exp=state.expenses.reduce((a,x)=>a+Number(x.amount),0),recv=state.invoices.reduce((a,x)=>a+Number(x.balance),0);return page('Dashboard Keuangan','Invoice, pembayaran, piutang, pengeluaran, kas/bank, dan akuntansi berada dalam satu kelompok menu Keuangan.',`<button class="btn btn-primary" onclick="openInvoiceForm()">＋ Invoice</button>`,`<div class="kpis"><div class="kpi"><span>Penerimaan</span><b>${money(inc)}</b></div><div class="kpi"><span>Pengeluaran</span><b>${money(exp)}</b></div><div class="kpi"><span>Piutang</span><b>${money(recv)}</b></div><div class="kpi"><span>Surplus Sederhana</span><b>${money(inc-exp)}</b></div></div><div class="grid2"><div>${card('Akses Cepat',`<div class="quick"><button onclick="go('invoices')">Invoice & Tagihan</button><button onclick="go('payments-receivables')">Pembayaran & Piutang</button><button onclick="go('expenses')">Pengeluaran</button><button onclick="go('accounting')">Jurnal & COA</button></div>`)}</div><div>${card('Rasio Penagihan',`<div style="font-size:42px;font-weight:900;color:var(--orange)">${Math.round(100*(state.invoices.reduce((a,x)=>a+Number(x.paid),0)/(state.invoices.reduce((a,x)=>a+Number(x.amount),0)||1)))}%</div><p class="muted">Persentase nilai invoice yang telah dibayar.</p>`)}</div></div>`)}
function invoicesPage(){let rows=state.invoices.map(x=>`<tr><td><b>${esc(x.invoiceNo)}</b></td><td>${esc(x.student)}</td><td>${esc(x.description)}</td><td>${esc(x.issue)}</td><td>${esc(x.due)}</td><td>${money(x.amount)}</td><td>${money(x.paid)}</td><td>${money(x.balance)}</td><td>${badge(x.status)}</td><td><div class="actions"><button class="btn btn-green btn-sm" onclick="openPaymentForm('${x.id}')">Bayar</button><button class="icon-btn" onclick="openInvoiceForm('${x.id}')">✎</button></div></td></tr>`);return page('Invoice & Tagihan','Course invoice, biaya pendaftaran, kursus, buku, ujian, diskon, cicilan, dan nomor dokumen.',`<button class="btn btn-primary" onclick="openInvoiceForm()">＋ Invoice</button>`,card('Daftar Invoice',table(['Invoice','Siswa','Deskripsi','Terbit','Jatuh Tempo','Nilai','Dibayar','Saldo','Status','Aksi'],rows)))}
function paymentsReceivablesPage(){let payRows=state.payments.map(x=>`<tr><td>${esc(x.paymentNo)}</td><td>${esc(x.date)}</td><td>${esc(x.student)}</td><td>${esc(x.method)}</td><td>${money(x.amount)}</td><td>${badge(x.status)}</td></tr>`),recRows=state.invoices.filter(x=>x.balance>0).map(x=>`<tr><td>${esc(x.student)}</td><td>${esc(x.invoiceNo)}</td><td>${esc(x.due)}</td><td>${money(x.balance)}</td><td>${badge(x.status)}</td><td><button class="btn btn-green btn-sm" onclick="openPaymentForm('${x.id}')">Terima Pembayaran</button></td></tr>`);return page('Pembayaran & Piutang','Pembayaran masuk, alokasi invoice, kuitansi, cicilan, reminder, dan outstanding student.',`<button class="btn btn-primary" onclick="openPaymentForm()">＋ Pembayaran</button>`,`<div data-tabs-root><div class="tabs" data-tabs><button class="tab active" data-tab="pay">Pembayaran</button><button class="tab" data-tab="recv">Piutang</button></div><div class="tab-panel active" data-panel="pay">${card('Pembayaran Masuk',table(['No. Pembayaran','Tanggal','Siswa','Metode','Jumlah','Status'],payRows))}</div><div class="tab-panel" data-panel="recv">${card('Piutang dan Angsuran',table(['Siswa','Invoice','Jatuh Tempo','Saldo','Status','Aksi'],recRows))}</div></div>`)}
function discountsPage(){return page('Diskon & Voucher','Diskon lunas, keluarga, promo, voucher, batas kewenangan, serta laporan penggunaan.',`<button class="btn btn-primary" onclick="toast('Form diskon/voucher dibuka')">＋ Diskon/Voucher</button>`,`<div class="panel-grid"><div class="module-tile"><div class="module-icon">5%</div><h3>Diskon Lunas</h3><p>Potongan otomatis bila pembayaran memenuhi syarat sebelum batas waktu.</p><b>Aktif: 5%</b></div><div class="module-tile"><div class="module-icon">家</div><h3>Diskon Keluarga</h3><p>Relasi antar siswa, persetujuan, dan masa berlaku.</p><b>Perlu verifikasi</b></div><div class="module-tile"><div class="module-icon">V</div><h3>Voucher</h3><p>Kode, nominal/persentase, kuota, target program, dan tanggal berlaku.</p><b>3 voucher aktif</b></div></div>`)}
function expensesPage(){let rows=state.expenses.map(x=>`<tr><td>${esc(x.documentNo)}</td><td>${esc(x.date)}</td><td>${esc(x.vendor)}</td><td>${esc(x.category)}</td><td>${money(x.amount)}</td><td>${badge(x.status)}</td><td>${actionButtons('expenses',x.id,'openExpenseForm')}</td></tr>`);return page('Pengeluaran & AP Invoice','Tagihan pemasok, pengeluaran operasional, bukti, jatuh tempo, approval, dan pembayaran keluar.',`<button class="btn btn-primary" onclick="openExpenseForm()">＋ Pengeluaran</button>`,card('Daftar Pengeluaran/AP Invoice',table(['Dokumen','Tanggal','Pemasok','Kategori','Nilai','Status','Aksi'],rows)))}
function cashBankPage(){let kas=state.accounts.find(x=>x.code==='1001'),bank=state.accounts.find(x=>x.code==='1002');return page('Kas, Bank & Petty Cash','Kas masuk/keluar, rekening bank, petty cash, top-up, cash advance, reimbursement, dan cash disbursement.',`<button class="btn btn-primary" onclick="toast('Transaksi kas baru dibuka')">＋ Transaksi</button>`,`<div class="kpis"><div class="kpi"><span>Kas</span><b>${money(kas?.balance)}</b></div><div class="kpi"><span>Bank</span><b>${money(bank?.balance)}</b></div><div class="kpi"><span>Cash Advance</span><b>${money(0)}</b></div><div class="kpi"><span>Reimbursement</span><b>${money(0)}</b></div></div><div class="panel-grid" style="margin-top:16px"><div class="module-tile"><div class="module-icon">PC</div><h3>Petty Cash</h3><p>Top-up, transaksi, bukti, saldo, dan rekonsiliasi.</p><button class="btn btn-soft btn-sm">Buka Buku Kas</button></div><div class="module-tile"><div class="module-icon">CA</div><h3>Cash Advance</h3><p>Pengajuan, persetujuan, pencairan, pertanggungjawaban, dan selisih.</p><button class="btn btn-soft btn-sm">Buka Pengajuan</button></div><div class="module-tile"><div class="module-icon">R</div><h3>Reimbursement</h3><p>Klaim, bukti, pemeriksaan, persetujuan, dan pembayaran.</p><button class="btn btn-soft btn-sm">Buka Klaim</button></div></div>`)}
function accountingPage(){let accRows=state.accounts.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.name)}</td><td>${esc(x.type)}</td><td>${money(x.balance)}</td><td>${x.active?badge('Aktif'):badge('Nonaktif')}</td><td>${actionButtons('accounts',x.id,'openAccountForm')}</td></tr>`),jrnRows=state.journals.map(x=>`<tr><td>${esc(x.journalNo)}</td><td>${esc(x.date)}</td><td>${esc(x.source)}</td><td>${esc(x.description)}</td><td>${esc(x.debit)}</td><td>${esc(x.credit)}</td><td>${badge(x.status)}</td></tr>`);return page('Akuntansi & Jurnal','Chart of account, cost center, account mapping, jurnal, buku besar, neraca saldo, neraca, dan laba-rugi.',`<button class="btn btn-outline" onclick="openAccountForm()">＋ Akun</button><button class="btn btn-primary" onclick="openJournalForm()">＋ Jurnal</button>`,`<div data-tabs-root><div class="tabs" data-tabs><button class="tab active" data-tab="coa">Chart of Account</button><button class="tab" data-tab="jrn">Jurnal</button><button class="tab" data-tab="report">Laporan Akuntansi</button></div><div class="tab-panel active" data-panel="coa">${card('Chart of Account',table(['Kode','Akun','Tipe','Saldo','Status','Aksi'],accRows))}</div><div class="tab-panel" data-panel="jrn">${card('Jurnal Umum',table(['No. Jurnal','Tanggal','Sumber','Deskripsi','Debit','Kredit','Status'],jrnRows))}</div><div class="tab-panel" data-panel="report"><div class="panel-grid"><div class="module-tile"><h3>General Ledger</h3><p>Buku besar per akun dan periode.</p><button class="btn btn-soft btn-sm">Tampilkan</button></div><div class="module-tile"><h3>Trial Balance</h3><p>Neraca saldo debit dan kredit.</p><button class="btn btn-soft btn-sm">Tampilkan</button></div><div class="module-tile"><h3>Balance Sheet & Profit/Loss</h3><p>Neraca dan laporan laba-rugi.</p><button class="btn btn-soft btn-sm">Tampilkan</button></div></div></div></div>`)}
function closingPage(){return page('Tutup Periode','Validasi transaksi, rekonsiliasi, posting jurnal, review neraca saldo, persetujuan, dan penguncian periode.',`<button class="btn btn-primary" onclick="toast('Checklist closing dijalankan')">Jalankan Pemeriksaan</button>`,`<div class="workflow"><div class="step">Transaksi Terverifikasi</div><span class="arrow">→</span><div class="step">Rekonsiliasi Kas/Bank</div><span class="arrow">→</span><div class="step">Jurnal Seimbang</div><span class="arrow">→</span><div class="step">Review Trial Balance</div><span class="arrow">→</span><div class="step">Kunci Periode</div></div><div class="panel-grid"><div class="module-tile"><h3>Periode 2026/3</h3><p>Status: terbuka. Terdapat 0 jurnal tidak seimbang dan 2 invoice belum lunas.</p>${badge('Belum Siap Closing')}</div><div class="module-tile"><h3>Hak Akses</h3><p>Hanya Pimpinan dan Akuntansi dapat menutup atau membuka kembali periode.</p>${badge('Audit Wajib')}</div><div class="module-tile"><h3>Backup</h3><p>Ekspor database dan backup dilakukan sebelum periode dikunci.</p><button class="btn btn-soft btn-sm" onclick="exportDatabase()">Backup JSON</button></div></div>`)}
function lettersPage(){let rows=state.letters.map(x=>`<tr><td>${esc(x.number)}</td><td>${esc(x.date)}</td><td>${esc(x.type)}</td><td>${esc(x.subject)}</td><td>${badge(x.status)}</td><td>${actionButtons('letters',x.id,'openLetterForm')}</td></tr>`);return page('Persuratan','Template, placeholder data, nomor dokumen, TTD/stempel, cetak, dan arsip.',`<button class="btn btn-primary" onclick="openLetterForm()">＋ Surat</button>`,card('Daftar Surat',table(['Nomor','Tanggal','Jenis','Perihal','Status','Aksi'],rows)))}
function announcementsPage(){let rows=state.announcements.map(x=>`<tr><td>${esc(x.publishDate)}</td><td><b>${esc(x.title)}</b><br><small>${esc(x.body)}</small></td><td>${esc(x.audience)}</td><td>${badge(x.status)}</td><td>${actionButtons('announcements',x.id,'openAnnouncementForm')}</td></tr>`);return page('Pengumuman & Notifikasi','Target audiens, tanggal tayang, kanal portal/WA/email, status terkirim, dan riwayat baca.',`<button class="btn btn-primary" onclick="openAnnouncementForm()">＋ Pengumuman</button>`,card('Pengumuman',table(['Tanggal','Pengumuman','Audiens','Status','Aksi'],rows)))}
function reportsPage(){let totalInvoice=state.invoices.reduce((a,x)=>a+Number(x.amount),0),paid=state.payments.reduce((a,x)=>a+Number(x.amount),0);return page('Laporan','Filter periode/program/kelas, drill-down ke sumber data, dan ekspor CSV/PDF.',`<button class="btn btn-outline" onclick="exportDatabase()">Ekspor Semua Data</button>`,`<div class="panel-grid"><div class="module-tile"><div class="module-icon">R</div><h3>Registrasi & Placement</h3><p>${state.leads.length} calon siswa, ${state.placements.length} placement.</p><button class="btn btn-soft btn-sm" onclick="exportStoreCSV('leads')">Ekspor</button></div><div class="module-tile"><div class="module-icon">S</div><h3>Siswa & Retensi</h3><p>${state.students.length} profil, ${state.students.filter(x=>x.status==='Aktif').length} aktif.</p><button class="btn btn-soft btn-sm" onclick="exportStoreCSV('students')">Ekspor</button></div><div class="module-tile"><div class="module-icon">K</div><h3>Kelas & Jadwal</h3><p>${state.classes.length} kelas, ${state.enrollments.length} enrollment.</p><button class="btn btn-soft btn-sm" onclick="exportStoreCSV('classes')">Ekspor</button></div><div class="module-tile"><div class="module-icon">A</div><h3>Akademik</h3><p>${state.attendance.length} absensi, ${state.scores.length} nilai.</p><button class="btn btn-soft btn-sm" onclick="exportStoreCSV('scores')">Ekspor</button></div><div class="module-tile"><div class="module-icon">Rp</div><h3>Keuangan</h3><p>Invoice ${money(totalInvoice)}, pembayaran ${money(paid)}.</p><button class="btn btn-soft btn-sm" onclick="exportStoreCSV('invoices')">Ekspor</button></div><div class="module-tile"><div class="module-icon">C</div><h3>Sertifikat</h3><p>Rekap sertifikat terbit, belum terbit, dan dibatalkan.</p><button class="btn btn-soft btn-sm">Tampilkan</button></div></div>`)}
function portalContentPage(){let rows=state.content.filter(x=>x.portal).map(x=>`<tr><td>${esc(x.type)}</td><td><b>${esc(x.title)}</b></td><td>${esc(x.date)}</td><td>${badge(x.status)}</td><td><button class="btn btn-soft btn-sm" onclick="openContentForm('${x.id}')">Edit</button></td></tr>`);return page('Kelola Konten Portal','Berita, kegiatan, galeri, Instagram, YouTube, dan pengumuman dapat diarahkan ke portal.',`<button class="btn btn-primary" onclick="openContentForm()">＋ Konten Portal</button>`,`${card('Konten Portal',table(['Jenis','Judul','Tanggal','Status','Aksi'],rows))}<div style="margin-top:16px">${card('Keterhubungan Konten',`<div class="workflow"><div class="step">Publikasi Lembaga</div><span class="arrow">→</span><div class="step">Target Portal = Ya</div><span class="arrow">→</span><div class="step">Tampil di Portal</div><span class="arrow">→</span><div class="step">Siswa/Orang Tua Membaca</div></div>`)}</div>`)}
function portalPreviewPage(){let student=state.students[0];return page('Pratinjau Portal','Pilih siswa untuk melihat jadwal, kehadiran, materi, nilai, invoice, pengumuman, berita, galeri, dan media sosial.',`<select id="portalStudentSelect" onchange="renderPortalStudent(this.value)">${state.students.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select>`,`<div id="portalPreviewHost">${portalMarkup(student?.id)}</div>`)}
function portalMarkup(studentId){let s=state.students.find(x=>x.id===studentId)||state.students[0];if(!s)return '<div class="empty">Belum ada siswa.</div>';let en=state.enrollments.find(e=>e.studentId===s.id&&e.status==='Aktif'),cl=state.classes.find(c=>c.id===en?.classId),inv=state.invoices.filter(i=>i.studentId===s.id),mats=state.materials.filter(m=>m.published&&(m.classId===cl?.id||m.program===s.program)),scores=state.scores.filter(x=>x.studentId===s.id),avg=scores.length?Math.round(scores.reduce((a,x)=>a+Number(x.score),0)/scores.length):0,contents=state.content.filter(x=>x.portal&&x.status==='Terbit').slice(0,4);return `<div class="preview-frame"><div class="preview-top"><small>PORTAL SISWA/ORANG TUA</small><h2 style="margin:5px 0">Halo, ${esc(s.name)}</h2><div>${esc(s.program)} • ${esc(s.level)} • ${esc(cl?.code||'Belum ditempatkan')}</div></div><div class="portal-grid"><div class="portal-box"><h4>Jadwal Kelas</h4><p>${esc(cl?.days||'-')}<br>${esc(cl?.time||'-')}<br>${esc(cl?.room||'-')}</p></div><div class="portal-box"><h4>Kehadiran</h4><p><b>${state.attendance.filter(a=>a.studentId===s.id&&a.status==='Hadir').length}</b> hadir tercatat</p></div><div class="portal-box"><h4>Nilai</h4><p><b>${avg||'-'}</b> rata-rata</p></div><div class="portal-box"><h4>Materi/Tugas</h4><p>${mats.length} materi tersedia</p></div><div class="portal-box"><h4>Invoice</h4><p>${money(inv.reduce((a,x)=>a+Number(x.balance),0))} saldo</p></div><div class="portal-box"><h4>Pengumuman</h4><p>${state.announcements.filter(x=>x.status==='Terbit').length} informasi terbaru</p></div></div><div class="portal-news">${contents.map(x=>`<article><img src="${x.image||'/assets/images/hero-main.jpg'}"><div><span class="badge b-blue">${esc(x.type)}</span><h4>${esc(x.title)}</h4><small>${esc(x.summary)}</small></div></article>`).join('')}</div></div>`}
function renderPortalStudent(id){portalPreviewHost.innerHTML=portalMarkup(id)}
function settingsPage(){let a=appSetting();return page('Pengaturan & Database','Identitas aplikasi, periode aktif, penomoran, backup, impor/ekspor, dan reset data demo.',`<button class="btn btn-primary" onclick="openAppSettings()">Edit Pengaturan</button>`,`<div class="grid-equal"><div>${card('Pengaturan Aktif',`<p><b>Periode:</b> ${esc(a.activePeriod)}</p><p><b>Prefix invoice:</b> ${esc(a.invoicePrefix)}</p><p><b>Prefix nomor murid:</b> ${esc(a.studentPrefix)}</p><p><b>Timeout sesi:</b> ${esc(a.sessionTimeout)} menit</p>`)}</div><div>${card('Database',`<p><b>Nama:</b> ${DB_NAME}</p><p><b>Teknologi prototype:</b> localStorage (standalone)</p><p><b>Object stores:</b> ${STORES.length}</p><div class="actions"><button class="btn btn-soft btn-sm" onclick="exportDatabase()">Ekspor JSON</button><label class="btn btn-outline btn-sm">Impor JSON<input type="file" hidden accept="application/json" onchange="importDatabase(this.files[0])"></label><button class="btn btn-danger btn-sm" onclick="resetDatabase()">Reset Demo</button></div>`)}</div></div><div style="margin-top:16px">${card('Audit Trail Terakhir',table(['Waktu','Aksi','Tabel','Entitas','Pengguna'],state.audit.slice(-12).reverse().map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.action)}</td><td>${esc(x.store)}</td><td>${esc(x.entityId)}</td><td>${esc(x.user)}</td></tr>`)))}</div>`)}

function formWrap(fields,submitLabel='Simpan'){return `<form onsubmit="genericFormSubmit(event)"><div class="form-grid">${fields}</div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px"><button type="button" class="btn btn-outline" onclick="closeModal()">Batal</button><button class="btn btn-primary">${submitLabel}</button></div></form>`}
let formContext=null;function genericFormSubmit(e){e.preventDefault();if(formContext)formContext(new FormData(e.target))}
function input(name,label,value='',type='text',extra=''){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}function textarea(name,label,value='',full=true){return `<div class="field ${full?'full':''}"><label>${label}</label><textarea name="${name}" rows="3">${esc(value)}</textarea></div>`}function select(name,label,options,value='',full=false){return `<div class="field ${full?'full':''}"><label>${label}</label><select name="${name}">${options.map(o=>{let val=Array.isArray(o)?o[0]:o,lab=Array.isArray(o)?o[1]:o;return `<option value="${esc(val)}" ${String(val)===String(value)?'selected':''}>${esc(lab)}</option>`}).join('')}</select></div>`}
function openOrgForm(){let o=org();formContext=async fd=>{let obj={...o,...Object.fromEntries(fd),id:'org',logo:o.logo};await save('settings',obj,'Perbarui profil lembaga');closeModal()};openModal('Edit Profil Lembaga',formWrap(input('name','Nama Lembaga',o.name,'text','required')+input('tagline','Tagline',o.tagline)+input('phone','WhatsApp',o.phone)+input('instagram','Instagram',o.instagram)+input('email','Email',o.email,'email')+input('address','Alamat',o.address)+input('website','Website',o.website)+input('map','Koordinat/Peta',o.map)+textarea('vision','Visi',o.vision)+textarea('mission','Misi',o.mission)))}
function openSimple(store,id,title,fields){let obj=id?state[store].find(x=>x.id===id):{};formContext=async fd=>{let x={...obj,...Object.fromEntries(fd),id:obj.id||uid(store.slice(0,3))};for(let f of fields){if(f.type==='number')x[f.name]=Number(x[f.name]||0);if(f.type==='checkbox')x[f.name]=fd.get(f.name)==='on'}await save(store,x,obj.id?'Perbarui':'Tambah');closeModal()};let html=fields.map(f=>f.type==='textarea'?textarea(f.name,f.label,obj[f.name]||'',f.full!==false):f.type==='select'?select(f.name,f.label,f.options,obj[f.name]||f.default||'',f.full):f.type==='checkbox'?`<div class="field"><label><input style="width:auto" type="checkbox" name="${f.name}" ${obj[f.name]!==false?'checked':''}> ${f.label}</label></div>`:input(f.name,f.label,obj[f.name]||f.default||'',f.type||'text',f.required?'required':'' )).join('');openModal(title,formWrap(html))}
function openFacilityForm(id){openSimple('facilities',id,id?'Edit Fasilitas':'Tambah Fasilitas',[{name:'name',label:'Nama Ruang',required:true},{name:'category',label:'Kategori'},{name:'location',label:'Lokasi/Lantai'},{name:'capacity',label:'Kapasitas',type:'number'},{name:'condition',label:'Kondisi',type:'select',options:['Baik','Perlu Perbaikan','Rusak']},{name:'status',label:'Status',type:'select',options:['Aktif','Nonaktif']}])}
function openAchievementForm(id){openSimple('achievements',id,id?'Edit Prestasi':'Tambah Prestasi',[{name:'title',label:'Judul',required:true},{name:'year',label:'Tahun'},{name:'category',label:'Kategori'},{name:'description',label:'Deskripsi',type:'textarea'}])}
function openProgramForm(id){openSimple('programs',id,id?'Edit Program':'Tambah Program',[{name:'code',label:'Kode',required:true},{name:'name',label:'Nama Program',required:true},{name:'segment',label:'Sasaran Peserta'},{name:'method',label:'Metode'},{name:'focus',label:'Fokus',type:'textarea'},{name:'duration',label:'Durasi'},{name:'levels',label:'Daftar Level',type:'textarea'},{name:'fee',label:'Biaya',type:'number'},{name:'active',label:'Program Aktif',type:'checkbox'}])}
function openPeriodForm(id){openSimple('periods',id,id?'Edit Periode':'Tambah Periode',[{name:'code',label:'Kode Periode',required:true},{name:'name',label:'Nama Periode'},{name:'start',label:'Tanggal Mulai',type:'date'},{name:'end',label:'Tanggal Selesai',type:'date'},{name:'status',label:'Status',type:'select',options:['Persiapan','Aktif','Tutup']}])}
function openEmployeeForm(id){openSimple('employees',id,id?'Edit Pegawai':'Tambah Pegawai',[{name:'name',label:'Nama Lengkap',required:true},{name:'role',label:'Jabatan',type:'select',options:['Pengajar','Front Office','Keuangan','Administrator','Pimpinan']},{name:'employment',label:'Status Kerja',type:'select',options:['Tetap','Kontrak','Freelance']},{name:'programs',label:'Kompetensi Program'},{name:'phone',label:'Kontak'},{name:'availability',label:'Ketersediaan'},{name:'status',label:'Status',type:'select',options:['Aktif','Nonaktif']}])}
function openLeadForm(id){openSimple('leads',id,id?'Edit Calon Siswa':'Tambah Calon Siswa',[{name:'name',label:'Nama Calon Siswa',required:true},{name:'phone',label:'WhatsApp',required:true},{name:'program',label:'Program',type:'select',options:state.programs.map(x=>x.code)},{name:'source',label:'Sumber',type:'select',options:['Website','Instagram','YouTube','Referensi','Walk-in']},{name:'stage',label:'Tahap',type:'select',options:['Baru','Placement Dijadwalkan','Menunggu Persetujuan','Menunggu Pembayaran','Aktif']},{name:'created',label:'Tanggal',type:'date',default:new Date().toISOString().slice(0,10)},{name:'note',label:'Catatan',type:'textarea'}])}
function openPlacementForm(id,leadId){let obj=id?state.placements.find(x=>x.id===id):{},lead=state.leads.find(x=>x.id===(leadId||obj.leadId));formContext=async fd=>{let x={...obj,...Object.fromEntries(fd),id:obj.id||uid('plc'),leadId:leadId||obj.leadId||fd.get('leadId'),score:Number(fd.get('score')||0)};await save('placements',x,obj.id?'Perbarui placement':'Tambah placement');let l=state.leads.find(z=>z.id===x.leadId);if(l){l.stage='Placement Dijadwalkan';await put('leads',l);await loadState()}closeModal()};openModal(id?'Edit Hasil Placement':'Jadwal Placement',formWrap(select('leadId','Calon Siswa',state.leads.map(x=>[x.id,x.name]),lead?.id||obj.leadId)+input('participant','Nama Peserta',obj.participant||lead?.name||'','text','required')+input('date','Tanggal',obj.date||new Date().toISOString().slice(0,10),'date')+input('time','Jam',obj.time||'10:00','time')+select('room','Ruang',state.facilities.filter(x=>/Ruang/.test(x.category)).map(x=>x.name),obj.room||'Ruang Placement')+select('examiner','Penguji',state.employees.filter(x=>x.role==='Pengajar').map(x=>x.name),obj.examiner||'')+input('score','Skor',obj.score||0,'number')+input('recommendation','Rekomendasi Program/Level',obj.recommendation||'')+select('status','Status',['Dijadwalkan','Menunggu Persetujuan','Disetujui','Ditolak'],obj.status||'Dijadwalkan')))}
async function schedulePlacement(leadId){openPlacementForm(null,leadId)}
async function approvePlacement(id){let p=state.placements.find(x=>x.id===id);p.status='Disetujui';await put('placements',p);let l=state.leads.find(x=>x.id===p.leadId);if(l){l.stage='Menunggu Pembayaran';await put('leads',l)}await loadState();renderCurrent();toast('Hasil placement disetujui')}
async function convertLeadToStudent(leadId){let l=state.leads.find(x=>x.id===leadId);let existing=state.students.find(x=>x.phone===l.phone&&x.name===l.name);if(existing){toast('Calon siswa sudah memiliki profil murid');return}let p=state.placements.find(x=>x.leadId===leadId&&x.status==='Disetujui'),rec=p?.recommendation||l.program+' Placement';let parts=rec.split(' '),program=parts.shift(),level=parts.join(' ')||'Placement';let s={id:uid('stu'),studentNo:(appSetting().studentPrefix||'LIA')+'-'+(26000+state.students.length+1),name:l.name,birthDate:'',gender:'',phone:l.phone,guardian:l.name,guardianPhone:l.phone,program,level,status:'Aktif'};await put('students',s);l.stage='Aktif';await put('leads',l);await loadState();openInvoiceForm(null,s.id);toast('Profil murid dibuat; lanjutkan pembuatan invoice')}
function openStudentForm(id){openSimple('students',id,id?'Edit Murid':'Tambah Murid',[{name:'studentNo',label:'Nomor Murid',default:(appSetting().studentPrefix||'LIA')+'-'+(26000+state.students.length+1)},{name:'name',label:'Nama Lengkap',required:true},{name:'birthDate',label:'Tanggal Lahir',type:'date'},{name:'gender',label:'Jenis Kelamin',type:'select',options:['Perempuan','Laki-laki']},{name:'phone',label:'Kontak Siswa'},{name:'guardian',label:'Nama Orang Tua/Wali'},{name:'guardianPhone',label:'Kontak Orang Tua/Wali'},{name:'program',label:'Program',type:'select',options:state.programs.map(x=>x.code)},{name:'level',label:'Level'},{name:'status',label:'Status',type:'select',options:['Aktif','Postponed','Alumni','Keluar']}])}
function openStudentDetail(id){let s=state.students.find(x=>x.id===id),en=state.enrollments.find(e=>e.studentId===id&&e.status==='Aktif'),cl=state.classes.find(c=>c.id===en?.classId),inv=state.invoices.filter(i=>i.studentId===id),scores=state.scores.filter(x=>x.studentId===id);openModal('Profil Murid — '+s.name,`<div data-tabs-root><div class="kpis"><div class="kpi"><span>Program/Level</span><b style="font-size:20px">${esc(s.program)} ${esc(s.level)}</b></div><div class="kpi"><span>Kelas</span><b style="font-size:16px">${esc(cl?.code||'-')}</b></div><div class="kpi"><span>Nilai</span><b>${scores.length?Math.round(scores.reduce((a,x)=>a+Number(x.score),0)/scores.length):'-'}</b></div><div class="kpi"><span>Piutang</span><b style="font-size:20px">${money(inv.reduce((a,x)=>a+Number(x.balance),0))}</b></div></div><div class="tabs" data-tabs><button class="tab active" data-tab="bio">Biodata</button><button class="tab" data-tab="class">Enrollment</button><button class="tab" data-tab="academic">Akademik</button><button class="tab" data-tab="finance">Keuangan</button><button class="tab" data-tab="portal">Portal</button></div><div class="tab-panel active" data-panel="bio"><div class="grid-equal"><div><p><b>No. Murid:</b> ${esc(s.studentNo)}</p><p><b>Nama:</b> ${esc(s.name)}</p><p><b>Tanggal Lahir:</b> ${esc(s.birthDate)}</p><p><b>Kontak:</b> ${esc(s.phone)}</p></div><div><p><b>Orang Tua/Wali:</b> ${esc(s.guardian)}</p><p><b>Kontak Wali:</b> ${esc(s.guardianPhone)}</p><p><b>Status:</b> ${badge(s.status)}</p></div></div></div><div class="tab-panel" data-panel="class"><p><b>Kelas aktif:</b> ${esc(cl?.code||'Belum ditempatkan')}</p><button class="btn btn-blue" onclick="closeModal();openAssignStudent('${s.id}')">Tempatkan/Pindah Kelas</button></div><div class="tab-panel" data-panel="academic">${table(['Komponen','Skor','Status'],scores.map(x=>`<tr><td>${esc(x.component)}</td><td>${x.score}</td><td>${badge(x.status)}</td></tr>`))}</div><div class="tab-panel" data-panel="finance">${table(['Invoice','Deskripsi','Nilai','Saldo','Status'],inv.map(x=>`<tr><td>${esc(x.invoiceNo)}</td><td>${esc(x.description)}</td><td>${money(x.amount)}</td><td>${money(x.balance)}</td><td>${badge(x.status)}</td></tr>`))}</div><div class="tab-panel" data-panel="portal"><button class="btn btn-primary" onclick="closeModal();go('portal-preview');setTimeout(()=>renderPortalStudent('${s.id}'),50)">Lihat Portal Siswa</button></div></div>`);bindTabs()}
function openLifecycleForm(){let students=state.students.map(x=>[x.id,x.name]);formContext=async fd=>{let s=state.students.find(x=>x.id===fd.get('studentId')),type=fd.get('type');if(type==='Postponed')s.status='Postponed';if(type==='Alumni')s.status='Alumni';if(type==='Aktif Kembali')s.status='Aktif';await put('students',s);await put('audit',{id:uid('aud'),time:new Date().toISOString(),action:type,store:'students',entityId:s.id,user:'Administrator',note:fd.get('note')});await loadState();closeModal();renderCurrent();toast('Status siswa diperbarui')};openModal('Pengajuan Perubahan Status',formWrap(select('studentId','Siswa',students)+select('type','Jenis',['Pindah Kelas','Postponed','Aktif Kembali','Alumni'])+textarea('note','Alasan/Catatan')))}
function openClassForm(id){openSimple('classes',id,id?'Edit Kelas':'Buat Kelas',[{name:'code',label:'Kode Kelas',required:true},{name:'program',label:'Program',type:'select',options:state.programs.map(x=>x.code)},{name:'level',label:'Level'},{name:'period',label:'Periode',type:'select',options:state.periods.map(x=>x.code)},{name:'teacher',label:'Pengajar',type:'select',options:state.employees.filter(x=>x.role==='Pengajar').map(x=>x.name)},{name:'room',label:'Ruang',type:'select',options:state.facilities.filter(x=>x.category.includes('Ruang')).map(x=>x.name)},{name:'days',label:'Hari'},{name:'time',label:'Jam'},{name:'capacity',label:'Kapasitas',type:'number'},{name:'status',label:'Status',type:'select',options:['Persiapan','Aktif','Selesai']}])}
function openClassDetail(id){let c=state.classes.find(x=>x.id===id),ens=state.enrollments.filter(e=>e.classId===id&&e.status==='Aktif'),members=ens.map(e=>state.students.find(s=>s.id===e.studentId)).filter(Boolean);openModal('Profil Kelas — '+c.code,`<div class="kpis"><div class="kpi"><span>Anggota</span><b>${members.length}/${c.capacity}</b></div><div class="kpi"><span>Pengajar</span><b style="font-size:17px">${esc(c.teacher)}</b></div><div class="kpi"><span>Jadwal</span><b style="font-size:15px">${esc(c.days)} ${esc(c.time)}</b></div><div class="kpi"><span>Ruang</span><b style="font-size:16px">${esc(c.room)}</b></div></div><div class="quick" style="margin-top:15px"><button onclick="closeModal();go('attendance')">Absensi</button><button onclick="closeModal();go('materials')">Materi</button><button onclick="closeModal();go('grading')">Nilai</button><button onclick="openAssignStudent(null,'${c.id}')">＋ Anggota</button></div><div style="margin-top:15px">${table(['No. Murid','Nama','Program/Level','Status','Aksi'],members.map(s=>`<tr><td>${esc(s.studentNo)}</td><td>${esc(s.name)}</td><td>${esc(s.program)} ${esc(s.level)}</td><td>${badge(s.status)}</td><td><button class="btn btn-danger btn-sm" onclick="removeEnrollment('${s.id}','${c.id}')">Keluarkan</button></td></tr>`))}</div>`)}
function openAssignStudent(studentId,classId){let sOpts=state.students.map(x=>[x.id,x.name+' — '+x.program+' '+x.level]),cOpts=state.classes.map(x=>[x.id,x.code]);formContext=async fd=>{let sid=studentId||fd.get('studentId'),cid=classId||fd.get('classId');let existing=state.enrollments.find(x=>x.studentId===sid&&x.status==='Aktif');if(existing){existing.status='Pindah';await put('enrollments',existing)}await put('enrollments',{id:uid('enr'),studentId:sid,classId:cid,date:new Date().toISOString().slice(0,10),status:'Aktif'});await put('audit',{id:uid('aud'),time:new Date().toISOString(),action:existing?'Pindah Kelas':'Tambah Anggota',store:'enrollments',entityId:sid,user:'Administrator'});await loadState();closeModal();renderCurrent();toast('Enrollment tersimpan')};openModal('Tempatkan Siswa ke Kelas',formWrap((studentId?`<p><b>Siswa:</b> ${esc(state.students.find(x=>x.id===studentId)?.name)}</p>`:select('studentId','Siswa',sOpts))+(classId?`<p><b>Kelas:</b> ${esc(state.classes.find(x=>x.id===classId)?.code)}</p>`:select('classId','Kelas',cOpts))))}
async function removeEnrollment(studentId,classId){let e=state.enrollments.find(x=>x.studentId===studentId&&x.classId===classId&&x.status==='Aktif');if(e){e.status='Keluar';await save('enrollments',e,'Keluarkan anggota');closeModal()}}
