function openInvoiceForm(id,studentId){let obj=id?state.invoices.find(x=>x.id===id):{},student=state.students.find(x=>x.id===(studentId||obj.studentId));formContext=async fd=>{let sid=studentId||obj.studentId||fd.get('studentId'),s=state.students.find(x=>x.id===sid),amount=Number(fd.get('amount')||0),paid=Number(obj.paid||0),x={...obj,...Object.fromEntries(fd),id:obj.id||uid('inv'),invoiceNo:obj.invoiceNo||(appSetting().invoicePrefix||'INV-LIA')+'-'+Date.now().toString().slice(-6),studentId:sid,student:s?.name||'',amount,paid,balance:Math.max(0,amount-paid),status:paid>=amount?'Lunas':paid>0?'Sebagian':'Belum Bayar'};await save('invoices',x,obj.id?'Perbarui invoice':'Buat invoice');closeModal()};openModal(id?'Edit Invoice':'Buat Invoice',formWrap((studentId?`<p><b>Siswa:</b> ${esc(student?.name)}</p>`:select('studentId','Siswa',state.students.map(x=>[x.id,x.name]),obj.studentId))+input('period','Periode',obj.period||appSetting().activePeriod)+input('description','Deskripsi',obj.description||((student?.program||'Kursus')+' '+(student?.level||'')),'text','required')+input('issue','Tanggal Terbit',obj.issue||new Date().toISOString().slice(0,10),'date')+input('due','Jatuh Tempo',obj.due||new Date(Date.now()+7*86400000).toISOString().slice(0,10),'date')+input('amount','Nilai Invoice',obj.amount||state.programs.find(p=>p.code===student?.program)?.fee||0,'number')))}
function openPaymentForm(invoiceId){let inv=state.invoices.find(x=>x.id===invoiceId)||state.invoices.find(x=>x.balance>0);formContext=async fd=>{let iid=fd.get('invoiceId'),i=state.invoices.find(x=>x.id===iid),amount=Number(fd.get('amount')||0);await put('payments',{id:uid('pay'),paymentNo:'PAY-'+Date.now().toString().slice(-6),invoiceId:iid,student:i.student,date:fd.get('date'),method:fd.get('method'),amount,status:'Terverifikasi'});i.paid=Number(i.paid||0)+amount;i.balance=Math.max(0,Number(i.amount)-i.paid);i.status=i.balance===0?'Lunas':'Sebagian';await put('invoices',i);await put('journals',{id:uid('jrn'),journalNo:'JU-'+Date.now().toString().slice(-6),date:fd.get('date'),source:'Pembayaran',description:'Pembayaran '+i.student,debit:'Bank '+money(amount),credit:'Pendapatan/Piutang '+money(amount),status:'Posted'});await loadState();closeModal();renderCurrent();toast('Pembayaran, alokasi invoice, dan jurnal tersimpan')};openModal('Terima Pembayaran',formWrap(select('invoiceId','Invoice',state.invoices.filter(x=>x.balance>0).map(x=>[x.id,x.invoiceNo+' — '+x.student+' — '+money(x.balance)]),inv?.id)+input('date','Tanggal',new Date().toISOString().slice(0,10),'date')+select('method','Metode',['Transfer Bank','Tunai','QRIS','Virtual Account'])+input('amount','Jumlah',inv?.balance||0,'number')))}
