function openContentForm(id,defaultType){let obj=id?state.content.find(x=>x.id===id):{};formContext=async fd=>{let x={...obj,...Object.fromEntries(fd),id:obj.id||uid('cnt'),public:fd.get('public')==='on',portal:fd.get('portal')==='on',image:obj.image||'/assets/images/hero-main.jpg'};await save('content',x,obj.id?'Perbarui konten':'Tambah konten');closeModal()};openModal(id?'Edit Konten':'Tambah Konten',formWrap(select('type','Jenis',['Berita','Kegiatan','Galeri','Instagram','YouTube'],obj.type||defaultType||'Berita')+input('title','Judul',obj.title||'','text','required')+textarea('summary','Ringkasan',obj.summary||'')+input('date','Tanggal',obj.date||new Date().toISOString().slice(0,10),'date')+input('url','Tautan Instagram/YouTube',obj.url||'')+input('platform','Platform',obj.platform||'')+select('status','Status',['Draft','Terbit','Berakhir'],obj.status||'Draft')+`<div class="field"><label><input style="width:auto" type="checkbox" name="public" ${obj.public!==false?'checked':''}> Tampilkan di Frontend Publik</label></div><div class="field"><label><input style="width:auto" type="checkbox" name="portal" ${obj.portal!==false?'checked':''}> Tampilkan di Portal Siswa/Orang Tua</label></div><div class="field full"><label>Gambar</label><input type="file" accept="image/*" onchange="contentImagePreview(this)"><img id="contentPreview" src="${obj.image||'/assets/images/hero-main.jpg'}" style="margin-top:8px;width:100%;max-height:220px;object-fit:cover;border-radius:12px"></div>`))}
