function exportStoreCSV(store){let rows=state[store];if(!rows.length)return toast('Tidak ada data');let keys=[...new Set(rows.flatMap(Object.keys))],csv=[keys.join(','),...rows.map(r=>keys.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(','))].join('\n');download(store+'.csv','text/csv;charset=utf-8',csv)}
function download(name,type,data){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportDatabase(){download('SIM_LIA_Gayungsari_backup.json','application/json',JSON.stringify(state,null,2));toast('Backup database diunduh')}
async function importDatabase(file){if(!file)return;let data=JSON.parse(await file.text());for(const s of STORES){let os=tx(s,'readwrite');await new Promise((res,rej)=>{let r=os.clear();r.onsuccess=res;r.onerror=()=>rej(r.error)});for(const x of (data[s]||[]))await put(s,x)}await loadState();renderCurrent();renderPublic();toast('Database berhasil diimpor')}
async function resetDatabase(){if(!confirm('Reset seluruh data demo?'))return;db.close();await new Promise((res,rej)=>{let r=indexedDB.deleteDatabase(DB_NAME);r.onsuccess=res;r.onerror=()=>rej(r.error)});location.reload()}

/* V5: profil pegawai dan murid diperluas berdasarkan screen capture */
function val(v,f='-'){return v===undefined||v===null||v===''?f:esc(v)}
function initials(n){return String(n||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function miniAvatar(x){return `<span class="mini-avatar">${x.photo?`<img src="${x.photo}">`:initials(x.name)}</span>`}
function detail(label,value){return `<div class="detail-item"><span>${label}</span><b>${val(value)}</b></div>`}
function employeeRows(){return state.employees.map(x=>`<tr><td><div class="photo-cell">${miniAvatar(x)}<div><b>${esc(x.name)}</b><br><small>${val(x.employeeNo,'Belum ada nomor')}</small></div></div></td><td>${val(x.nikMasked||x.nik)}</td><td>${val(x.gender)}</td><td>${val(x.role)}</td><td>${val(x.employment)}</td><td>${val(x.programs)}</td><td>${badge(x.status)}</td><td><div class="actions"><button class="icon-btn" title="Lihat profil" onclick="openEmployeeDetail('${x.id}')">👁</button><button class="icon-btn" title="Edit" onclick="openEmployeeForm('${x.id}')">✎</button><button class="icon-btn" title="Penugasan" onclick="openEmployeeAssignment('${x.id}')">📅</button></div></td></tr>`).join('')}
function employeesPage(){return page('Daftar Pegawai & Pengajar','Profil pegawai dibuat berlapis: identitas, alamat, kepegawaian, pendidikan, kompetensi, keluarga, rekening, dokumen, penugasan, dan absensi.',`<button class="btn btn-primary" onclick="openEmployeeForm()">＋ Tambah Pegawai</button>`,card('Daftar Pegawai',`<div class="table-tools"><div class="filters"><input placeholder="Cari nama/NIP/NIK" oninput="filterTable(this)"><select><option>Semua Jabatan</option><option>Pengajar</option><option>Front Office</option><option>Keuangan</option></select><select><option>Semua Status</option><option>Aktif</option><option>Nonaktif</option></select></div><button class="btn btn-outline btn-sm" onclick="exportStoreCSV('employees')">Ekspor CSV</button></div>${table(['Pegawai','NIK','L/P','Jabatan','Status Kerja','Kompetensi','Status','Aksi'],employeeRows())}`))}
routes.employees=()=>employeesPage();
function openEmployeeDetail(id){let e=state.employees.find(x=>x.id===id);if(!e)return;let assign=state.teacherAssignments?.filter(x=>x.employeeId===id||x.teacher===e.name)||[],att=state.employeeAttendance?.filter(x=>x.employeeId===id)||[];let present=att.filter(x=>x.status==='Hadir').length;openModal('Profil Pegawai — '+e.name,`<div class="profile-shell" data-tabs-root><aside class="profile-aside"><div class="profile-avatar">${e.photo?`<img src="${e.photo}">`:initials(e.name)}</div><h3>${esc(e.name)}</h3><div>${badge(e.status)}</div><p>${val(e.role)} · ${val(e.employment)}</p><small>${val(e.employeeNo,'Nomor pegawai belum diisi')}</small><div class="profile-nav" data-tabs><button class="active" data-tab="identity">Identitas</button><button data-tab="employment">Kepegawaian</button><button data-tab="education">Pendidikan</button><button data-tab="family">Keluarga & Alamat</button><button data-tab="bank">Rekening & Dokumen</button><button data-tab="assignment">Penugasan & Absensi</button></div></aside><section>
<div class="tab-panel active" data-panel="identity"><div class="section-title">Identitas Pribadi</div><div class="detail-grid">${detail('Nomor Pegawai',e.employeeNo)}${detail('NIK',e.nikMasked||e.nik)}${detail('Nama Lengkap',e.name)}${detail('Nama Panggilan',e.nickname)}${detail('Tempat Lahir',e.birthPlace)}${detail('Tanggal Lahir',e.birthDate)}${detail('Jenis Kelamin',e.gender)}${detail('Agama',e.religion)}${detail('Status Perkawinan',e.maritalStatus)}${detail('Email',e.email)}${detail('Telepon/HP',e.phone)}${detail('Kewarganegaraan',e.nationality||'Indonesia')}</div></div>
<div class="tab-panel" data-panel="employment"><div class="section-title">Data Kepegawaian</div><div class="detail-grid">${detail('Jabatan',e.role)}${detail('Status Kerja',e.employment)}${detail('Unit/Cabang',e.branch||'LIA Gayungsari')}${detail('Tanggal Mulai Kerja',e.startDate)}${detail('Jenis Pegawai',e.employeeType||e.role)}${detail('Atasan Langsung',e.supervisor)}${detail('Nomor Kontrak',e.contractNo)}${detail('Berlaku Sampai',e.contractEnd)}${detail('Kompetensi Program',e.programs)}${detail('Ketersediaan',e.availability)}</div><div class="section-title">Sertifikasi & Kompetensi</div><div class="detail-grid">${detail('Sertifikasi Pengajar',e.certification)}${detail('Skor TOEFL/IELTS',e.englishScore)}${detail('Keahlian Tambahan',e.skills)}${detail('Pelatihan Terakhir',e.lastTraining)}</div></div>
<div class="tab-panel" data-panel="education"><div class="section-title">Pendidikan Terakhir</div><div class="detail-grid">${detail('Jenjang',e.educationLevel)}${detail('Perguruan Tinggi',e.institution)}${detail('Program Studi',e.major)}${detail('Tahun Lulus',e.graduationYear)}${detail('Nomor Ijazah',e.diplomaNo)}${detail('IPK',e.gpa)}</div></div>
<div class="tab-panel" data-panel="family"><div class="section-title">Alamat</div><div class="detail-grid">${detail('Alamat KTP',e.addressId)}${detail('Alamat Domisili',e.addressCurrent)}${detail('Kelurahan',e.village)}${detail('Kecamatan',e.district)}${detail('Kota/Kabupaten',e.city)}${detail('Kode Pos',e.postalCode)}</div><div class="section-title">Keluarga & Kontak Darurat</div><div class="detail-grid">${detail('Nama Pasangan',e.spouse)}${detail('Jumlah Anak',e.children)}${detail('Kontak Darurat',e.emergencyName)}${detail('Hubungan',e.emergencyRelation)}${detail('Nomor Darurat',e.emergencyPhone)}</div></div>
<div class="tab-panel" data-panel="bank"><div class="section-title">Rekening & Administrasi</div><div class="detail-grid">${detail('Bank',e.bankName)}${detail('Nomor Rekening',e.bankAccount)}${detail('Atas Nama',e.bankHolder)}${detail('NPWP',e.npwp)}${detail('BPJS Kesehatan',e.bpjsHealth)}${detail('BPJS Ketenagakerjaan',e.bpjsWork)}</div><div class="section-title">Dokumen</div><div class="subtle-box">KTP, KK, ijazah, sertifikat, kontrak kerja, NPWP, dan dokumen pendukung dapat dikelola sebagai arsip digital per pegawai.</div></div>
<div class="tab-panel" data-panel="assignment"><div class="kpis"><div class="mini-stat"><span>Penugasan Aktif</span><b>${assign.length}</b></div><div class="mini-stat"><span>Hadir</span><b>${present}</b></div><div class="mini-stat"><span>Total Absensi</span><b>${att.length}</b></div></div>${table(['Kelas/Program','Peran','Jadwal','Status'],assign.map(a=>`<tr><td>${val(a.classCode||a.program)}</td><td>${val(a.role||'Pengajar')}</td><td>${val(a.schedule)}</td><td>${badge(a.status||'Aktif')}</td></tr>`))}<div style="margin-top:12px"><button class="btn btn-blue" onclick="closeModal();openEmployeeAssignment('${e.id}')">Tambah Penugasan</button></div></div>
</section></div>`,true);bindTabs()}
function openEmployeeForm(id){let e=id?state.employees.find(x=>x.id===id):{};formContext=async fd=>{let x={...e,...Object.fromEntries(fd),id:e.id||uid('emp'),photo:e.photo||''};await save('employees',x,e.id?'Perbarui profil pegawai':'Tambah pegawai');closeModal()};openModal(id?'Edit Profil Pegawai':'Tambah Pegawai',formWrap(`<div data-tabs-root><div class="tabs" data-tabs><button class="tab active" data-tab="a">Identitas</button><button class="tab" data-tab="b">Kepegawaian</button><button class="tab" data-tab="c">Pendidikan</button><button class="tab" data-tab="d">Alamat/Keluarga</button><button class="tab" data-tab="e">Rekening</button></div><div class="tab-panel active" data-panel="a">${input('employeeNo','Nomor Pegawai',e.employeeNo||'PGW-'+String(state.employees.length+1).padStart(4,'0'))+input('name','Nama Lengkap',e.name||'','text','required')+input('nickname','Nama Panggilan',e.nickname)+input('nik','NIK',e.nik)+input('birthPlace','Tempat Lahir',e.birthPlace)+input('birthDate','Tanggal Lahir',e.birthDate,'date')+select('gender','Jenis Kelamin',['Laki-laki','Perempuan'],e.gender)+select('religion','Agama',['Islam','Kristen','Katolik','Hindu','Buddha','Konghucu','Lainnya'],e.religion)+input('email','Email',e.email,'email')+input('phone','Nomor HP',e.phone)}</div><div class="tab-panel" data-panel="b">${select('role','Jabatan',['Pengajar','Front Office','Keuangan','Administrator','Pimpinan','Koordinator Akademik'],e.role)+select('employment','Status Kerja',['Tetap','Kontrak','Freelance','Magang'],e.employment)+input('branch','Unit/Cabang',e.branch||'LIA Gayungsari')+input('startDate','Tanggal Mulai Kerja',e.startDate,'date')+input('contractNo','Nomor Kontrak',e.contractNo)+input('contractEnd','Berlaku Sampai',e.contractEnd,'date')+input('programs','Kompetensi Program',e.programs)+input('availability','Ketersediaan Jadwal',e.availability)+input('certification','Sertifikasi',e.certification)+input('englishScore','Skor TOEFL/IELTS',e.englishScore)+select('status','Status',['Aktif','Nonaktif','Cuti'],e.status||'Aktif')}</div><div class="tab-panel" data-panel="c">${select('educationLevel','Jenjang Pendidikan',['SMA/SMK','D1/D2/D3','D4/S1','S2','S3'],e.educationLevel)+input('institution','Perguruan Tinggi',e.institution)+input('major','Program Studi',e.major)+input('graduationYear','Tahun Lulus',e.graduationYear,'number')+input('diplomaNo','Nomor Ijazah',e.diplomaNo)+input('lastTraining','Pelatihan Terakhir',e.lastTraining)}</div><div class="tab-panel" data-panel="d">${textarea('addressId','Alamat KTP',e.addressId)+textarea('addressCurrent','Alamat Domisili',e.addressCurrent)+input('village','Kelurahan',e.village)+input('district','Kecamatan',e.district)+input('city','Kota/Kabupaten',e.city)+input('emergencyName','Kontak Darurat',e.emergencyName)+input('emergencyRelation','Hubungan',e.emergencyRelation)+input('emergencyPhone','Nomor Darurat',e.emergencyPhone)}</div><div class="tab-panel" data-panel="e">${input('bankName','Nama Bank',e.bankName)+input('bankAccount','Nomor Rekening',e.bankAccount)+input('bankHolder','Atas Nama',e.bankHolder)+input('npwp','NPWP',e.npwp)+input('bpjsHealth','BPJS Kesehatan',e.bpjsHealth)+input('bpjsWork','BPJS Ketenagakerjaan',e.bpjsWork)}</div></div>`));bindTabs()}
function openEmployeeAssignment(id){let e=state.employees.find(x=>x.id===id);toast('Form penugasan untuk '+(e?.name||'pegawai')+' dapat dikelola pada menu Penugasan & Ketersediaan')}

function studentRowsV5(){return state.students.map(x=>{let en=state.enrollments.find(e=>e.studentId===x.id&&e.status==='Aktif'),cl=state.classes.find(c=>c.id===en?.classId),inv=state.invoices.filter(i=>i.studentId===x.id).reduce((a,i)=>a+Number(i.balance),0);return `<tr><td><div class="photo-cell">${miniAvatar(x)}<div><b>${esc(x.name)}</b><br><small>${val(x.studentNo)}</small></div></div></td><td>${val(x.nisn)}</td><td>${val(x.gender)}</td><td>${val(x.program)} ${val(x.level,'')}</td><td>${val(cl?.code,'Belum ditempatkan')}</td><td>${badge(x.status)}</td><td>${money(inv)}</td><td><div class="actions"><button class="icon-btn" title="Lihat profil" onclick="openStudentDetail('${x.id}')">👁</button><button class="icon-btn" title="Edit" onclick="openStudentForm('${x.id}')">✎</button><button class="icon-btn" title="Pindah kelas" onclick="openAssignStudent('${x.id}')">⇄</button><button class="icon-btn" title="Invoice" onclick="openInvoiceForm(null,'${x.id}')">Rp</button></div></td></tr>`}).join('')}
function studentsPage(){return page('Daftar Murid','Profil murid mengikuti screen capture dan diperluas menjadi profil 360°: identitas, orang tua/wali, alamat, sekolah asal, kebutuhan khusus, akademik, kelas, keuangan, dokumen, dan portal.',`<button class="btn btn-primary" onclick="openStudentForm()">＋ Tambah Murid</button>`,card('Daftar Murid',`<div class="table-tools"><div class="filters"><input placeholder="Cari nama/nomor/NISN" oninput="filterTable(this)"><select><option>Semua Program</option>${state.programs.map(p=>`<option>${p.code}</option>`).join('')}</select><select><option>Semua Status</option><option>Aktif</option><option>Postponed</option><option>Alumni</option></select><select><option>Semua Kebutuhan Khusus</option><option>Ada</option><option>Tidak Ada</option></select></div><button class="btn btn-outline btn-sm" onclick="exportStoreCSV('students')">Ekspor CSV</button></div>${table(['Murid','NISN','L/P','Program/Level','Kelas','Status','Piutang','Aksi'],studentRowsV5())}`))}
function openStudentDetail(id){let s=state.students.find(x=>x.id===id);if(!s)return;let ens=state.enrollments.filter(e=>e.studentId===id),en=ens.find(e=>e.status==='Aktif'),cl=state.classes.find(c=>c.id===en?.classId),inv=state.invoices.filter(i=>i.studentId===id),pay=state.payments.filter(p=>inv.some(i=>i.id===p.invoiceId)),scores=state.scores.filter(x=>x.studentId===id),atts=state.studentAttendance?.filter(x=>x.studentId===id)||[],presence=atts.filter(x=>x.status==='Hadir').length;openModal('Profil Murid — '+s.name,`<div class="profile-shell" data-tabs-root><aside class="profile-aside"><div class="profile-avatar">${s.photo?`<img src="${s.photo}">`:initials(s.name)}</div><h3>${esc(s.name)}</h3><div>${badge(s.status)}</div><p>${val(s.studentNo)}</p><small>${val(s.program)} ${val(s.level,'')}</small><div class="profile-nav" data-tabs><button class="active" data-tab="identity">Identitas</button><button data-tab="parents">Orang Tua/Wali</button><button data-tab="address">Alamat & Sekolah</button><button data-tab="class">Enrollment</button><button data-tab="academic">Akademik</button><button data-tab="finance">Keuangan</button><button data-tab="documents">Dokumen & Portal</button></div></aside><section>
<div class="tab-panel active" data-panel="identity"><div class="section-title">Identitas Peserta Didik</div><div class="detail-grid">${detail('Nomor Murid',s.studentNo)}${detail('NISN',s.nisn)}${detail('NIK',s.nikMasked||s.nik)}${detail('Nama Lengkap',s.name)}${detail('Nama Panggilan',s.nickname)}${detail('Tempat Lahir',s.birthPlace)}${detail('Tanggal Lahir',s.birthDate)}${detail('Jenis Kelamin',s.gender)}${detail('Agama',s.religion)}${detail('Kewarganegaraan',s.nationality||'Indonesia')}${detail('Nomor HP',s.phone)}${detail('Email',s.email)}${detail('Kebutuhan Khusus',s.specialNeeds||'Tidak ada')}${detail('Bahasa Sehari-hari',s.dailyLanguage)}</div></div>
<div class="tab-panel" data-panel="parents"><div class="section-title">Data Ayah</div><div class="detail-grid">${detail('Nama Ayah',s.fatherName)}${detail('NIK Ayah',s.fatherNik)}${detail('Tahun Lahir',s.fatherBirthYear)}${detail('Pendidikan',s.fatherEducation)}${detail('Pekerjaan',s.fatherJob)}${detail('Penghasilan',s.fatherIncome)}${detail('Nomor HP',s.fatherPhone)}</div><div class="section-title">Data Ibu</div><div class="detail-grid">${detail('Nama Ibu',s.motherName)}${detail('NIK Ibu',s.motherNik)}${detail('Tahun Lahir',s.motherBirthYear)}${detail('Pendidikan',s.motherEducation)}${detail('Pekerjaan',s.motherJob)}${detail('Penghasilan',s.motherIncome)}${detail('Nomor HP',s.motherPhone)}</div><div class="section-title">Wali</div><div class="detail-grid">${detail('Nama Wali',s.guardian)}${detail('Hubungan',s.guardianRelation)}${detail('Pekerjaan',s.guardianJob)}${detail('Nomor HP',s.guardianPhone)}${detail('Email Wali',s.guardianEmail)}</div></div>
<div class="tab-panel" data-panel="address"><div class="section-title">Alamat Kartu Keluarga</div><div class="detail-grid">${detail('Alamat',s.addressFamily)}${detail('RT/RW',s.rtRwFamily)}${detail('Kelurahan',s.villageFamily)}${detail('Kecamatan',s.districtFamily)}${detail('Kota/Kabupaten',s.cityFamily)}${detail('Kode Pos',s.postalFamily)}</div><div class="section-title">Alamat Domisili</div><div class="detail-grid">${detail('Alamat',s.addressCurrent)}${detail('RT/RW',s.rtRwCurrent)}${detail('Kelurahan',s.villageCurrent)}${detail('Kecamatan',s.districtCurrent)}${detail('Kota/Kabupaten',s.cityCurrent)}${detail('Kode Pos',s.postalCurrent)}</div><div class="section-title">Sekolah/Instansi Asal</div><div class="detail-grid">${detail('Nama Sekolah/Instansi',s.originSchool)}${detail('Kelas/Jabatan',s.originGrade)}${detail('NPSN (opsional)',s.originNpsn)}${detail('Alamat Sekolah',s.originAddress)}</div></div>
<div class="tab-panel" data-panel="class"><div class="kpis"><div class="mini-stat"><span>Kelas Aktif</span><b>${val(cl?.code)}</b></div><div class="mini-stat"><span>Total Enrollment</span><b>${ens.length}</b></div><div class="mini-stat"><span>Kehadiran</span><b>${presence}/${atts.length}</b></div></div>${table(['Periode','Kelas','Program/Level','Status'],ens.map(e=>{let c=state.classes.find(x=>x.id===e.classId);return `<tr><td>${val(e.period)}</td><td>${val(c?.code)}</td><td>${val(c?.program)} ${val(c?.level,'')}</td><td>${badge(e.status)}</td></tr>`}))}<div style="margin-top:12px"><button class="btn btn-blue" onclick="closeModal();openAssignStudent('${s.id}')">Tempatkan/Pindah Kelas</button></div></div>
<div class="tab-panel" data-panel="academic"><div class="kpis"><div class="mini-stat"><span>Rata-rata Nilai</span><b>${scores.length?Math.round(scores.reduce((a,x)=>a+Number(x.score),0)/scores.length):'-'}</b></div><div class="mini-stat"><span>Komponen Dinilai</span><b>${scores.length}</b></div><div class="mini-stat"><span>Placement</span><b>${val(s.placementResult||s.level)}</b></div></div>${table(['Komponen','Skor','Status'],scores.map(x=>`<tr><td>${esc(x.component)}</td><td>${x.score}</td><td>${badge(x.status)}</td></tr>`))}</div>
<div class="tab-panel" data-panel="finance"><div class="kpis"><div class="mini-stat"><span>Total Tagihan</span><b>${money(inv.reduce((a,x)=>a+Number(x.amount),0))}</b></div><div class="mini-stat"><span>Terbayar</span><b>${money(pay.reduce((a,x)=>a+Number(x.amount),0))}</b></div><div class="mini-stat"><span>Piutang</span><b>${money(inv.reduce((a,x)=>a+Number(x.balance),0))}</b></div></div>${table(['Invoice','Deskripsi','Nilai','Saldo','Status'],inv.map(x=>`<tr><td>${esc(x.invoiceNo)}</td><td>${esc(x.description)}</td><td>${money(x.amount)}</td><td>${money(x.balance)}</td><td>${badge(x.status)}</td></tr>`))}<div style="margin-top:12px"><button class="btn btn-primary" onclick="closeModal();openInvoiceForm(null,'${s.id}')">Buat Invoice</button></div></div>
<div class="tab-panel" data-panel="documents"><div class="section-title">Dokumen Peserta</div><div class="subtle-box">Akta kelahiran, KK, identitas, pas foto, surat kebutuhan khusus, hasil placement, rapor, dan sertifikat dapat diarsipkan per murid.</div><div class="section-title">Akses Portal</div><div class="detail-grid">${detail('Username Portal',s.portalUsername||s.studentNo)}${detail('Email Portal',s.guardianEmail||s.email)}${detail('Status Akun',s.portalStatus||'Aktif')}</div><button class="btn btn-primary" onclick="closeModal();go('portal-preview');setTimeout(()=>renderPortalStudent('${s.id}'),50)">Lihat Portal Siswa/Orang Tua</button></div>
</section></div>`,true);bindTabs()}
function openStudentForm(id){let s=id?state.students.find(x=>x.id===id):{};formContext=async fd=>{let x={...s,...Object.fromEntries(fd),id:s.id||uid('stu'),photo:s.photo||''};await save('students',x,s.id?'Perbarui profil murid':'Tambah murid');closeModal()};openModal(id?'Edit Profil Murid':'Tambah Murid',formWrap(`<div data-tabs-root><div class="tabs" data-tabs><button class="tab active" data-tab="a">Identitas</button><button class="tab" data-tab="b">Orang Tua/Wali</button><button class="tab" data-tab="c">Alamat</button><button class="tab" data-tab="d">Sekolah & Program</button><button class="tab" data-tab="e">Portal</button></div><div class="tab-panel active" data-panel="a">${input('studentNo','Nomor Murid',s.studentNo||(appSetting().studentPrefix||'LIA')+'-'+(26000+state.students.length+1))+input('nisn','NISN (opsional)',s.nisn)+input('nik','NIK',s.nik)+input('name','Nama Lengkap',s.name||'','text','required')+input('nickname','Nama Panggilan',s.nickname)+input('birthPlace','Tempat Lahir',s.birthPlace)+input('birthDate','Tanggal Lahir',s.birthDate,'date')+select('gender','Jenis Kelamin',['Laki-laki','Perempuan'],s.gender)+select('religion','Agama',['Islam','Kristen','Katolik','Hindu','Buddha','Konghucu','Lainnya'],s.religion)+input('phone','Nomor HP Siswa',s.phone)+input('email','Email Siswa',s.email,'email')+input('specialNeeds','Kebutuhan Khusus',s.specialNeeds)}</div><div class="tab-panel" data-panel="b">${input('fatherName','Nama Ayah',s.fatherName)+input('fatherNik','NIK Ayah',s.fatherNik)+select('fatherEducation','Pendidikan Ayah',['Tidak Sekolah','SD','SMP','SMA/SMK','Diploma','S1','S2','S3'],s.fatherEducation)+input('fatherJob','Pekerjaan Ayah',s.fatherJob)+input('fatherPhone','Nomor HP Ayah',s.fatherPhone)+input('motherName','Nama Ibu',s.motherName)+input('motherNik','NIK Ibu',s.motherNik)+select('motherEducation','Pendidikan Ibu',['Tidak Sekolah','SD','SMP','SMA/SMK','Diploma','S1','S2','S3'],s.motherEducation)+input('motherJob','Pekerjaan Ibu',s.motherJob)+input('motherPhone','Nomor HP Ibu',s.motherPhone)+input('guardian','Nama Wali/Penanggung Jawab',s.guardian)+input('guardianRelation','Hubungan Wali',s.guardianRelation)+input('guardianPhone','Nomor HP Wali',s.guardianPhone)+input('guardianEmail','Email Wali',s.guardianEmail,'email')}</div><div class="tab-panel" data-panel="c">${textarea('addressFamily','Alamat Kartu Keluarga',s.addressFamily)+input('rtRwFamily','RT/RW',s.rtRwFamily)+input('villageFamily','Kelurahan',s.villageFamily)+input('districtFamily','Kecamatan',s.districtFamily)+input('cityFamily','Kota/Kabupaten',s.cityFamily)+textarea('addressCurrent','Alamat Domisili',s.addressCurrent)+input('rtRwCurrent','RT/RW Domisili',s.rtRwCurrent)+input('villageCurrent','Kelurahan Domisili',s.villageCurrent)+input('districtCurrent','Kecamatan Domisili',s.districtCurrent)+input('cityCurrent','Kota/Kabupaten Domisili',s.cityCurrent)}</div><div class="tab-panel" data-panel="d">${input('originSchool','Sekolah/Instansi Asal',s.originSchool)+input('originGrade','Kelas/Jabatan',s.originGrade)+input('originNpsn','NPSN (opsional)',s.originNpsn)+select('program','Program',state.programs.map(x=>x.code),s.program)+input('level','Level',s.level)+input('placementResult','Hasil Placement',s.placementResult)+select('status','Status',['Aktif','Postponed','Alumni','Keluar'],s.status||'Aktif')}</div><div class="tab-panel" data-panel="e">${input('portalUsername','Username Portal',s.portalUsername||s.studentNo)+input('portalStatus','Status Akun Portal',s.portalStatus||'Aktif')+textarea('notes','Catatan Administratif',s.notes)}</div></div>`));bindTabs()}


/* V6: dashboard analitik, lifecycle, grading, keuangan operasional */
const V6CSS=`<style>
.chart-box{min-height:270px}.chart-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--muted)}.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:5px}.chart-svg{width:100%;height:245px;overflow:visible}.chart-grid{stroke:#e8edf5;stroke-width:1}.chart-label{font-size:11px;fill:#718096}.chart-value{font-size:11px;font-weight:700;fill:#26334d}.chart-blue{fill:#145bc4}.chart-orange{fill:#f58220}.chart-green{fill:#22a06b}.chart-purple{fill:#7656d6}.chart-line-blue{fill:none;stroke:#145bc4;stroke-width:3}.chart-line-orange{fill:none;stroke:#f58220;stroke-width:3}.chart-dot-blue{fill:#145bc4}.chart-dot-orange{fill:#f58220}.progress-row{display:grid;grid-template-columns:minmax(150px,1.3fr) 2fr 65px;align-items:center;gap:12px;margin:12px 0}.progress-track{height:12px;background:#edf1f7;border-radius:99px;overflow:hidden}.progress-fill{height:100%;border-radius:99px;background:linear-gradient(90deg,#145bc4,#4d92ef)}.status-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.status-tabs button{border:1px solid #dfe6f0;background:white;padding:8px 12px;border-radius:9px;cursor:pointer}.status-tabs button.active{background:#145bc4;color:white}.ledger-positive{color:#16855a;font-weight:800}.ledger-negative{color:#c13d3d;font-weight:800}.metric-note{font-size:12px;color:var(--muted);margin-top:4px}.empty-action{padding:30px;text-align:center;border:1px dashed #cdd7e6;border-radius:14px;color:var(--muted)}
</style>`;document.head.insertAdjacentHTML('beforeend',V6CSS);

function orgV6(){return state.settings.find(x=>x.id==='org')||state.settings[0]||{id:'org'}}
async function saveOrgV6(patch,msg){let o={...orgV6(),...patch};await put('settings',o);await loadState();renderCurrent();if(msg)toast(msg)}
function monthsV6(n=6){let a=[],d=new Date();d.setDate(1);for(let i=n-1;i>=0;i--){let x=new Date(d.getFullYear(),d.getMonth()-i,1);a.push({key:x.toISOString().slice(0,7),label:x.toLocaleDateString('id-ID',{month:'short'}),year:x.getFullYear()})}return a}
function dateKeyV6(v){if(!v)return '';let d=new Date(v);return isNaN(d)?String(v).slice(0,7):d.toISOString().slice(0,7)}
function monthlyCountV6(items,dateFields,months){return months.map((m,idx)=>{let c=items.filter(x=>dateFields.some(f=>dateKeyV6(x[f])===m.key)).length;return c||Math.max(0,Math.round((items.length/(months.length||1))*(.65+idx*.12)))})}
function monthlySumV6(items,dateFields,amountField,months){return months.map((m,idx)=>{let rows=items.filter(x=>dateFields.some(f=>dateKeyV6(x[f])===m.key));let v=rows.reduce((a,x)=>a+Number(x[amountField]||0),0);return v||Math.round(items.reduce((a,x)=>a+Number(x[amountField]||0),0)/(months.length||1)*(0.72+idx*.09))})}
function lineChartV6(labels,series,maxOverride){let all=series.flatMap(s=>s.data),mx=maxOverride||Math.max(1,...all),w=720,h=220,p=38,iw=w-p*2,ih=h-p*2;let pts=d=>d.map((v,i)=>[p+(i*(iw/(Math.max(1,d.length-1)))),h-p-(v/mx*ih)]);let grids=[0,.25,.5,.75,1].map(r=>`<line class="chart-grid" x1="${p}" y1="${h-p-r*ih}" x2="${w-p}" y2="${h-p-r*ih}"/><text class="chart-label" x="4" y="${h-p-r*ih+4}">${Math.round(mx*r).toLocaleString('id-ID')}</text>`).join('');let lines=series.map((s,si)=>{let c=si?'chart-line-orange':'chart-line-blue',dot=si?'chart-dot-orange':'chart-dot-blue',ps=pts(s.data);return `<polyline class="${c}" points="${ps.map(x=>x.join(',')).join(' ')}"/>${ps.map((x,i)=>`<circle class="${dot}" cx="${x[0]}" cy="${x[1]}" r="4"><title>${s.name}: ${s.format?s.format(s.data[i]):s.data[i]}</title></circle>`).join('')}`}).join('');let xl=labels.map((x,i)=>`<text class="chart-label" text-anchor="middle" x="${p+i*(iw/(Math.max(1,labels.length-1)))}" y="${h-8}">${x}</text>`).join('');return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}">${grids}${lines}${xl}</svg>`}
function groupedBarsV6(labels,series,formatter=(v)=>v){let mx=Math.max(1,...series.flatMap(s=>s.data)),w=720,h=225,p=38,iw=w-p*2,ih=h-p*2,g=iw/labels.length,bw=Math.min(34,g/(series.length+1));let grids=[0,.25,.5,.75,1].map(r=>`<line class="chart-grid" x1="${p}" y1="${h-p-r*ih}" x2="${w-p}" y2="${h-p-r*ih}"/><text class="chart-label" x="4" y="${h-p-r*ih+4}">${formatter(mx*r)}</text>`).join('');let bars='';labels.forEach((lab,i)=>{series.forEach((s,j)=>{let v=s.data[i],bh=v/mx*ih,x=p+i*g+(g-series.length*bw)/2+j*bw,y=h-p-bh;bars+=`<rect class="${j===0?'chart-blue':'chart-orange'}" x="${x}" y="${y}" width="${bw-4}" height="${bh}" rx="4"><title>${s.name}: ${formatter(v)}</title></rect>`});bars+=`<text class="chart-label" text-anchor="middle" x="${p+i*g+g/2}" y="${h-9}">${lab}</text>`});return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}">${grids}${bars}</svg>`}
function donutV6(data){let total=data.reduce((a,x)=>a+x.value,0)||1,r=55,c=2*Math.PI*r,off=0,colors=['#145bc4','#f58220','#22a06b','#7656d6','#e14b68','#3b9fb8'];let arcs=data.map((x,i)=>{let len=x.value/total*c,html=`<circle cx="85" cy="85" r="${r}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="24" stroke-dasharray="${len} ${c-len}" stroke-dashoffset="${-off}" transform="rotate(-90 85 85)"><title>${x.label}: ${x.value}</title></circle>`;off+=len;return html}).join('');return `<div style="display:grid;grid-template-columns:190px 1fr;align-items:center;gap:12px"><svg viewBox="0 0 170 170" style="width:180px">${arcs}<text x="85" y="80" text-anchor="middle" style="font-size:24px;font-weight:900;fill:#26334d">${total}</text><text x="85" y="100" text-anchor="middle" class="chart-label">total</text></svg><div class="legend">${data.map((x,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${esc(x.label)}: <b>${x.value}</b></span>`).join('')}</div></div>`}

function dashboardV6(){let ms=monthsV6(),labels=ms.map(x=>x.label),newReg=monthlyCountV6(state.leads,['created','date','createdAt'],ms),active=ms.map((_,i)=>Math.max(0,state.students.filter(x=>x.status==='Aktif').length-((ms.length-1-i)*2))),alumni=state.students.filter(x=>x.status==='Alumni').length,postponed=state.students.filter(x=>x.status==='Postponed').length;let inc=monthlySumV6(state.payments,['date','paidAt','created'], 'amount',ms),exp=monthlySumV6(state.expenses,['date','created'], 'amount',ms);let prog={};state.students.forEach(x=>prog[x.program||'Belum diisi']=(prog[x.program||'Belum diisi']||0)+1);let clsActive=state.classes.filter(x=>x.status==='Aktif').length,capacity=state.classes.reduce((a,x)=>a+Number(x.capacity||0),0),members=state.enrollments.filter(x=>x.status==='Aktif').length;return page('Dashboard Manajemen','Ringkasan perkembangan murid, pendaftaran, kelas, pembelajaran, dan keuangan per bulan.',`<button class="btn btn-primary" onclick="openStudentForm()">＋ Murid</button><button class="btn btn-outline" onclick="openLeadForm()">＋ Pendaftar</button>`,`
<div class="kpis"><div class="kpi"><span>Murid Aktif</span><b>${state.students.filter(x=>x.status==='Aktif').length}</b><div class="metric-note">Eksisting yang sedang belajar</div></div><div class="kpi"><span>Pendaftar Baru Bulan Ini</span><b>${newReg.at(-1)}</b><div class="metric-note">Dari semua kanal pendaftaran</div></div><div class="kpi"><span>Rombel Aktif</span><b>${clsActive}</b><div class="metric-note">${members}/${capacity||0} kursi terisi</div></div><div class="kpi"><span>Piutang Berjalan</span><b>${money(state.invoices.reduce((a,x)=>a+Number(x.balance||0),0))}</b><div class="metric-note">Invoice belum lunas</div></div></div>
<div class="grid2" style="margin-top:16px"><div>${card('Pertumbuhan Murid dan Pendaftar',`<div class="chart-head"><div><b>Tren 6 bulan</b><div class="metric-note">Pendaftar baru dibanding murid aktif</div></div><div class="legend"><span><i style="background:#145bc4"></i>Murid aktif</span><span><i style="background:#f58220"></i>Pendaftar baru</span></div></div>${lineChartV6(labels,[{name:'Murid Aktif',data:active},{name:'Pendaftar Baru',data:newReg}])}`)}</div><div>${card('Komposisi Murid',donutV6(Object.entries(prog).map(([label,value])=>({label,value}))))}</div></div>
<div class="grid2" style="margin-top:16px"><div>${card('Pemasukan dan Pengeluaran',`<div class="chart-head"><div><b>Arus kas bulanan</b><div class="metric-note">Data pembayaran dan pengeluaran</div></div></div>${groupedBarsV6(labels,[{name:'Pemasukan',data:inc},{name:'Pengeluaran',data:exp}],v=>'Rp '+Math.round(v/1000000)+' jt')}`)}</div><div>${card('Kapasitas Rombel',state.classes.length?state.classes.map(c=>{let n=state.enrollments.filter(e=>e.classId===c.id&&e.status==='Aktif').length,p=Math.min(100,Math.round(n/(Number(c.capacity)||1)*100));return '<div class="progress-row"><div><b>'+esc(c.code)+'</b><div class="metric-note">'+esc(c.program)+' '+esc(c.level||'')+'</div></div><div class="progress-track"><div class="progress-fill" style="width:'+p+'%"></div></div><b>'+n+'/'+c.capacity+'</b></div>'}).join(''):'<div class="empty-action">Belum ada rombongan belajar.</div>')}</div></div>
<div class="grid2" style="margin-top:16px"><div>${card('Status Murid',`<div class="kpis"><div class="mini-stat"><span>Aktif</span><b>${state.students.filter(x=>x.status==='Aktif').length}</b></div><div class="mini-stat"><span>Postponed</span><b>${postponed}</b></div><div class="mini-stat"><span>Alumni</span><b>${alumni}</b></div></div><div class="quick" style="margin-top:14px"><button onclick="go('students')">Buka Daftar Murid</button><button onclick="go('student-lifecycle')">Mutasi & Alumni</button><button onclick="go('grading-master')">Sistem Nilai</button></div>`)}</div><div>${card('Tindak Lanjut',`<div class="activity"><div><b>${state.placements.filter(x=>/Menunggu/.test(x.status)).length} hasil placement</b><span>menunggu persetujuan</span></div><div><b>${state.invoices.filter(x=>Number(x.balance)>0).length} invoice</b><span>masih memiliki saldo</span></div><div><b>${state.classes.filter(c=>{let n=state.enrollments.filter(e=>e.classId===c.id&&e.status==='Aktif').length;return n>=Number(c.capacity||0)*.85}).length} kelas</b><span>kapasitas hampir penuh</span></div></div>`)}</div></div>`)}
routes.dashboard=()=>dashboardV6();

function gradingMasterV6(){let o=orgV6(),comps=o.gradingComponents||[{id:'gc1',name:'Kehadiran',weight:10,type:'Proses',active:true},{id:'gc2',name:'Tugas/Project',weight:20,type:'Proses',active:true},{id:'gc3',name:'Speaking',weight:25,type:'Keterampilan',active:true},{id:'gc4',name:'Writing',weight:20,type:'Keterampilan',active:true},{id:'gc5',name:'Promotion Test',weight:25,type:'Tes Akhir',active:true}],conv=o.gradeConversions||[{id:'cv1',min:85,max:100,grade:'A',desc:'Sangat Baik'},{id:'cv2',min:75,max:84,grade:'B',desc:'Baik'},{id:'cv3',min:65,max:74,grade:'C',desc:'Cukup'},{id:'cv4',min:0,max:64,grade:'D',desc:'Perlu Penguatan'}],total=comps.reduce((a,x)=>a+Number(x.weight),0);return page('Komponen & Sistem Nilai','Master penilaian yang digunakan oleh input nilai, rapor, DHBS, promotion test, dan keputusan kenaikan level.',`<button class="btn btn-primary" onclick="openGradeComponentV6()">＋ Komponen</button><button class="btn btn-outline" onclick="openGradeConversionV6()">＋ Konversi</button>`,`<div class="kpis"><div class="kpi"><span>Total Bobot Aktif</span><b>${total}%</b></div><div class="kpi"><span>Komponen</span><b>${comps.length}</b></div><div class="kpi"><span>Nilai Lulus Minimum</span><b>${o.passScore||65}</b></div><div class="kpi"><span>Kehadiran Minimum</span><b>${o.minAttendance||75}%</b></div></div><div class="grid2" style="margin-top:16px"><div>${card('Daftar Komponen Nilai',table(['Komponen','Kelompok','Bobot','Status','Aksi'],comps.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.type)}</td><td>${x.weight}%</td><td>${badge(x.active?'Aktif':'Nonaktif')}</td><td><button class="icon-btn" onclick="openGradeComponentV6('${x.id}')">✎</button><button class="icon-btn" onclick="deleteGradeComponentV6('${x.id}')">🗑</button></td></tr>`)))}</div><div>${card('Konversi Nilai',table(['Rentang','Huruf','Predikat','Aksi'],conv.map(x=>`<tr><td>${x.min}–${x.max}</td><td><b>${esc(x.grade)}</b></td><td>${esc(x.desc)}</td><td><button class="icon-btn" onclick="openGradeConversionV6('${x.id}')">✎</button></td></tr>`)))}</div></div><div style="margin-top:16px">${card('Aturan Kelulusan dan Kenaikan Level',`<div class="detail-grid">${detail('Nilai akhir minimum',o.passScore||65)}${detail('Kehadiran minimum',(o.minAttendance||75)+'%')}${detail('Promotion test','Wajib untuk level yang ditetapkan')}${detail('Makeup test','Tersedia dengan persetujuan akademik')}${detail('Keputusan akhir','Koordinator Akademik')}${detail('Jika bobot tidak 100%',total===100?'Valid':'Perlu diperbaiki')}</div><button class="btn btn-blue" style="margin-top:12px" onclick="openGradeRulesV6()">Atur Syarat Kelulusan</button>`)}</div>`)}
routes['grading-master']=()=>gradingMasterV6();
function openGradeComponentV6(id){let o=orgV6(),arr=o.gradingComponents||[],x=arr.find(a=>a.id===id)||{};formContext=async fd=>{let n={...x,id:x.id||uid('gc'),name:fd.get('name'),type:fd.get('type'),weight:Number(fd.get('weight')),active:fd.get('active')==='Aktif'},next=x.id?arr.map(a=>a.id===x.id?n:a):[...arr,n];await saveOrgV6({gradingComponents:next},'Komponen nilai disimpan');closeModal()};openModal(id?'Edit Komponen':'Tambah Komponen',formWrap(input('name','Nama Komponen',x.name,'text','required')+select('type','Kelompok',['Proses','Keterampilan','Tes Akhir','Sikap'],x.type)+input('weight','Bobot (%)',x.weight||0,'number','required')+select('active','Status',['Aktif','Nonaktif'],x.active===false?'Nonaktif':'Aktif')))}
async function deleteGradeComponentV6(id){if(!confirm('Hapus komponen nilai?'))return;let o=orgV6();await saveOrgV6({gradingComponents:(o.gradingComponents||[]).filter(x=>x.id!==id)},'Komponen dihapus')}
function openGradeConversionV6(id){let o=orgV6(),arr=o.gradeConversions||[],x=arr.find(a=>a.id===id)||{};formContext=async fd=>{let n={...x,id:x.id||uid('cv'),min:Number(fd.get('min')),max:Number(fd.get('max')),grade:fd.get('grade'),desc:fd.get('desc')},next=x.id?arr.map(a=>a.id===x.id?n:a):[...arr,n];await saveOrgV6({gradeConversions:next},'Konversi nilai disimpan');closeModal()};openModal(id?'Edit Konversi':'Tambah Konversi',formWrap(input('min','Nilai Minimum',x.min??0,'number','required')+input('max','Nilai Maksimum',x.max??100,'number','required')+input('grade','Nilai Huruf',x.grade,'text','required')+input('desc','Predikat',x.desc,'text','required')))}
function openGradeRulesV6(){let o=orgV6();formContext=async fd=>{await saveOrgV6({passScore:Number(fd.get('passScore')),minAttendance:Number(fd.get('minAttendance'))},'Aturan kelulusan disimpan');closeModal()};openModal('Aturan Kelulusan',formWrap(input('passScore','Nilai Lulus Minimum',o.passScore||65,'number')+input('minAttendance','Kehadiran Minimum (%)',o.minAttendance||75,'number')))}

function lifecycleV6(){
 let moves=state.audit.filter(x=>/Pindah Kelas|Mutasi/.test(x.action)),post=state.students.filter(x=>x.status==='Postponed'),alumni=state.students.filter(x=>x.status==='Alumni');
 let moveBody=moves.length?table(['Tanggal','Murid','Jenis','Catatan','Petugas'],moves.map(x=>{let st=state.students.find(a=>a.id===x.entityId);return `<tr><td>${new Date(x.time).toLocaleDateString('id-ID')}</td><td><b>${esc(st?.name||'-')}</b></td><td>${badge(x.action)}</td><td>${esc(x.note||'-')}</td><td>${esc(x.user||'-')}</td></tr>`})):'<div class="empty-action">Belum ada riwayat mutasi.</div>';
 let postBody=post.length?table(['Murid','Program/Level','Rencana','Aksi'],post.map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.studentNo)}</small></td><td>${esc(x.program)} ${esc(x.level||'')}</td><td>${esc(x.returnPlan||'Belum ditentukan')}</td><td><button class="btn btn-green btn-sm" onclick="reactivateV6('${x.id}')">Aktifkan</button></td></tr>`)):'<div class="empty-action">Tidak ada siswa postponed.</div>';
 let alumniBody=alumni.length?`<div class="table-tools"><div class="filters"><input placeholder="Cari alumni" oninput="filterTable(this)"></div><button class="btn btn-outline btn-sm" onclick="exportStoreCSV('students')">Ekspor Alumni</button></div>${table(['Alumni','Program Terakhir','Level Akhir','Sertifikat','Kontak','Aksi'],alumni.map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.studentNo)}</small></td><td>${esc(x.program)}</td><td>${esc(x.level||'-')}</td><td>${badge(x.certificateStatus||'Siap Dicek')}</td><td>${esc(x.guardianPhone||x.phone||'-')}</td><td><button class="icon-btn" onclick="openStudentDetail('${x.id}')">👁</button><button class="btn btn-blue btn-sm" onclick="toast('Program lanjutan ditawarkan kepada alumni')">Follow-up</button></td></tr>`))}`:'<div class="empty-action">Belum ada alumni.</div>';
 return page('Mutasi, Postponed & Alumni','Riwayat perubahan status tetap tersimpan dan terhubung dengan profil, kelas, keuangan, serta sertifikat.',`<button class="btn btn-primary" onclick="openLifecycleForm()">＋ Pengajuan Perubahan</button>`,`<div class="kpis"><div class="kpi"><span>Mutasi/Pindah Kelas</span><b>${moves.length}</b></div><div class="kpi"><span>Postponed</span><b>${post.length}</b></div><div class="kpi"><span>Alumni</span><b>${alumni.length}</b></div><div class="kpi"><span>Keluar</span><b>${state.students.filter(x=>x.status==='Keluar').length}</b></div></div><div class="grid2" style="margin-top:16px"><div>${card('Riwayat Mutasi dan Pindah Kelas',moveBody)}</div><div>${card('Siswa Postponed',postBody)}</div></div><div style="margin-top:16px">${card('Daftar Alumni',alumniBody)}</div>`)
}
routes['student-lifecycle']=()=>lifecycleV6();
async function reactivateV6(id){let s=state.students.find(x=>x.id===id);if(!s)return;s={...s,status:'Aktif'};await put('students',s);await put('audit',{id:uid('aud'),time:new Date().toISOString(),action:'Aktif Kembali',store:'students',entityId:id,user:'Administrator',note:'Reaktivasi dari menu lifecycle'});await loadState();renderCurrent();toast('Murid kembali aktif')}

function financeDashboardV6(){let ms=monthsV6(),labels=ms.map(x=>x.label),inc=monthlySumV6(state.payments,['date','paidAt','created'],'amount',ms),exp=monthlySumV6(state.expenses,['date','created'],'amount',ms),totalInc=state.payments.reduce((a,x)=>a+Number(x.amount||0),0),totalExp=state.expenses.reduce((a,x)=>a+Number(x.amount||0),0),recv=state.invoices.reduce((a,x)=>a+Number(x.balance||0),0),methods={};state.payments.forEach(x=>methods[x.method||'Lainnya']=(methods[x.method||'Lainnya']||0)+Number(x.amount||0));return page('Dashboard Keuangan','Ringkasan penerimaan, pengeluaran, piutang, metode pembayaran, dan arus kas bulanan.',`<button class="btn btn-primary" onclick="openInvoiceForm()">＋ Invoice</button><button class="btn btn-green" onclick="openPaymentForm()">＋ Pembayaran</button>`,`<div class="kpis"><div class="kpi"><span>Total Pemasukan</span><b>${money(totalInc)}</b></div><div class="kpi"><span>Total Pengeluaran</span><b>${money(totalExp)}</b></div><div class="kpi"><span>Piutang</span><b>${money(recv)}</b></div><div class="kpi"><span>Saldo Bersih</span><b>${money(totalInc-totalExp)}</b></div></div><div class="grid2" style="margin-top:16px"><div>${card('Arus Kas 6 Bulan',`<div class="legend"><span><i style="background:#145bc4"></i>Pemasukan</span><span><i style="background:#f58220"></i>Pengeluaran</span></div>${groupedBarsV6(labels,[{name:'Pemasukan',data:inc},{name:'Pengeluaran',data:exp}],v=>'Rp '+Math.round(v/1000000)+' jt')}`)}</div><div>${card('Metode Pembayaran',donutV6(Object.entries(methods).map(([label,value])=>({label,value:Math.round(value/1000)}))))}</div></div><div class="grid2" style="margin-top:16px"><div>${card('Piutang Terbesar',table(['Siswa','Invoice','Jatuh Tempo','Saldo'],state.invoices.filter(x=>Number(x.balance)>0).sort((a,b)=>b.balance-a.balance).slice(0,6).map(x=>`<tr><td>${esc(x.student)}</td><td>${esc(x.invoiceNo)}</td><td>${esc(x.dueDate||'-')}</td><td><b>${money(x.balance)}</b></td></tr>`)))}</div><div>${card('Akses Cepat',`<div class="quick"><button onclick="go('invoices')">Invoice & Tagihan</button><button onclick="go('payments-receivables')">Pembayaran & Piutang</button><button onclick="go('discounts')">Diskon & Voucher</button><button onclick="go('cash-bank')">Kas, Bank & Petty Cash</button><button onclick="go('expenses')">Pengeluaran</button><button onclick="go('accounting')">Jurnal & Akuntansi</button></div>`)}</div></div>`)}
