const EXTRA_STORES=['teacherAssignments','employeeAttendance','studentDocuments','employeeDocuments','parentCommunications','counselingNotes','dataChanges'];
EXTRA_STORES.forEach(s=>{if(!STORES.includes(s))STORES.push(s)});

function deepClone(v){return JSON.parse(JSON.stringify(v))}
function ensureStores(){STORES.forEach(s=>{if(!Array.isArray(state[s]))state[s]=[]})}
function persistState(){
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true}
  catch(e){console.error('Gagal menyimpan localStorage',e);toast('Penyimpanan browser penuh. Ekspor backup lalu kurangi foto/dokumen.');return false}
}
function openDB(){return Promise.resolve({name:DB_NAME,technology:'localStorage'})}
function tx(){throw new Error('Adapter transaksi lama tidak digunakan pada versi standalone')}
function all(store){return Promise.resolve(deepClone(state[store]||[]))}
function put(store,obj){
  ensureStores();
  const arr=state[store];
  const i=arr.findIndex(x=>x.id===obj.id);
  if(i>=0)arr[i]=deepClone(obj);else arr.push(deepClone(obj));
  persistState();
  return Promise.resolve(obj)
}
function del(store,id){
  ensureStores();state[store]=(state[store]||[]).filter(x=>x.id!==id);persistState();return Promise.resolve()
}
async function loadState(){
  let raw=null;
  try{raw=localStorage.getItem(STORAGE_KEY)}catch(e){console.warn(e)}
  if(raw){
    try{state=JSON.parse(raw)||{}}catch(e){console.warn('Backup lokal rusak, memakai data awal',e);state={}}
  }else state={};
  ensureStores();
  return state
}
async function seedIfNeeded(){
  if((state.settings||[]).length)return;
  state={};
  STORES.forEach(s=>state[s]=deepClone(SEED[s]||[]));
  enhanceSeedData();
  persistState()
}
