function table(headers,rows){
  const body=Array.isArray(rows)?rows.join(''):String(rows||'');
  return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="empty">Belum ada data.</td></tr>`}</tbody></table></div>`
}
async function importDatabase(file){
  if(!file)return;
  try{
    const data=JSON.parse(await file.text());
    const next={};STORES.forEach(s=>next[s]=Array.isArray(data[s])?data[s]:[]);
    state=next;ensureStores();persistState();await loadState();renderCurrent();renderPublic();toast('Backup berhasil diimpor')
  }catch(e){console.error(e);toast('File backup tidak valid')}
}
async function resetDatabase(){
  if(!confirm('Reset seluruh data prototype ke data awal?'))return;
  localStorage.removeItem(STORAGE_KEY);state={};await loadState();await seedIfNeeded();renderMenu();renderPublic();renderCurrent();toast('Data demo berhasil direset')
}
function storageBytes(){try{return new Blob([localStorage.getItem(STORAGE_KEY)||'']).size}catch(e){return 0}}
function settingsPage(){let a=appSetting(),kb=Math.round(storageBytes()/1024);return page('Pengaturan & Penyimpanan','Identitas aplikasi, periode aktif, penomoran, backup, impor/ekspor, dan reset data standalone.',`<button class="btn btn-primary" onclick="openAppSettings()">Edit Pengaturan</button>`,`<div class="storage-note"><span>●</span><div><b>Mode standalone aktif.</b><br>Semua data disimpan pada browser perangkat ini melalui localStorage. Lakukan ekspor JSON secara berkala untuk cadangan.</div></div><div class="grid-equal" style="margin-top:16px"><div>${card('Pengaturan Aktif',`<p><b>Periode:</b> ${esc(a.activePeriod)}</p><p><b>Prefix invoice:</b> ${esc(a.invoicePrefix)}</p><p><b>Prefix nomor murid:</b> ${esc(a.studentPrefix)}</p><p><b>Timeout sesi:</b> ${esc(a.sessionTimeout)} menit</p>`)}</div><div>${card('Penyimpanan Lokal',`<p><b>Kunci:</b> ${STORAGE_KEY}</p><p><b>Teknologi:</b> localStorage</p><p><b>Kelompok data:</b> ${STORES.length}</p><p><b>Ukuran saat ini:</b> ${kb} KB</p><div class="actions"><button class="btn btn-soft btn-sm" onclick="exportDatabase()">Ekspor JSON</button><label class="btn btn-outline btn-sm">Impor JSON<input type="file" hidden accept="application/json" onchange="importDatabase(this.files[0])"></label><button class="btn btn-danger btn-sm" onclick="resetDatabase()">Reset Demo</button></div>`)}</div></div><div style="margin-top:16px">${card('Audit Trail Terakhir',table(['Waktu','Aksi','Data','Entitas','Pengguna'],state.audit.slice(-12).reverse().map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.action)}</td><td>${esc(x.store)}</td><td>${esc(x.entityId)}</td><td>${esc(x.user)}</td></tr>`)))}</div>`)}

