function fileToCompressedDataURL(file,max=520,quality=.82){return new Promise((resolve,reject)=>{let r=new FileReader();r.onerror=reject;r.onload=()=>{let img=new Image();img.onerror=reject;img.onload=()=>{let scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.round(img.width*scale),h=Math.round(img.height*scale),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',quality))};img.src=r.result};r.readAsDataURL(file)})}
function openPhotoManager(store,id){let obj=(state[store]||[]).find(x=>x.id===id);if(!obj)return;formContext=async()=>{let f=document.getElementById('profilePhotoFile')?.files?.[0];if(!f){toast('Pilih foto terlebih dahulu');return}obj.photo=await fileToCompressedDataURL(f);await save(store,obj,'Perbarui foto');closeModal()};openModal('Foto Profil — '+(obj.name||''),formWrap(`<div class="field full"><div class="file-drop"><div style="font-size:34px">📷</div><b>Ambil foto atau pilih dari perangkat</b><p class="muted">Foto otomatis diperkecil agar penyimpanan browser tetap ringan.</p><input id="profilePhotoFile" type="file" accept="image/*" capture="user" required></div></div>`,'Simpan Foto'))}

function teacherAssignmentPage(){let rows=(state.teacherAssignments||[]).map(a=>{let e=state.employees.find(x=>x.id===a.employeeId),c=state.classes.find(x=>x.id===a.classId);return `<tr><td><b>${esc(e?.name||a.teacher||'-')}</b></td><td>${esc(c?.code||a.classCode||'-')}</td><td>${esc(a.program||c?.program||'-')}</td><td>${esc(a.role||'Pengajar')}</td><td>${esc(a.schedule||'-')}</td><td>${badge(a.status||'Aktif')}</td><td><button class="icon-btn" onclick="openEmployeeAssignment('${a.employeeId}','${a.id}')">✎</button><button class="icon-btn" onclick="removeItem('teacherAssignments','${a.id}')">🗑</button></td></tr>`});return page('Penugasan & Ketersediaan','Penugasan pegawai terhubung dengan profil, program, kelas, jadwal, dan status penugasan.',`<button class="btn btn-primary" onclick="openEmployeeAssignment()">＋ Penugasan</button>`,card('Daftar Penugasan',table(['Pegawai','Kelas','Program','Peran','Jadwal','Status','Aksi'],rows)))}
function openEmployeeAssignment(employeeId,assignmentId){let a=assignmentId?(state.teacherAssignments||[]).find(x=>x.id===assignmentId):{},employeeOptions=state.employees.map(x=>[x.id,x.name+' — '+x.role]),classOptions=state.classes.map(x=>[x.id,x.code+' — '+x.program+' '+(x.level||'')]);formContext=async fd=>{let eid=employeeId||fd.get('employeeId'),cid=fd.get('classId'),e=state.employees.find(x=>x.id===eid),c=state.classes.find(x=>x.id===cid),x={...a,id:a.id||uid('teach'),employeeId:eid,teacher:e?.name||'',classId:cid,classCode:c?.code||'',program:fd.get('program')||c?.program||'',role:fd.get('role'),schedule:fd.get('schedule')||((c?.days||'')+' '+(c?.time||'')),status:fd.get('status')};await save('teacherAssignments',x,a.id?'Perbarui penugasan':'Tambah penugasan');closeModal()};let fixed=employeeId?`<div class="field"><label>Pegawai</label><div class="subtle-box"><b>${esc(state.employees.find(x=>x.id===employeeId)?.name||'-')}</b></div></div>`:select('employeeId','Pegawai',employeeOptions,a.employeeId);openModal(a.id?'Edit Penugasan':'Tambah Penugasan',formWrap(fixed+select('classId','Kelas/Rombel',classOptions,a.classId)+select('program','Program',state.programs.map(x=>x.code),a.program)+select('role','Peran',['Pengajar Utama','Pengajar Pendamping','Substitusi','Koordinator'],a.role||'Pengajar Utama')+input('schedule','Jadwal',a.schedule)+select('status','Status',['Aktif','Selesai','Dibatalkan'],a.status||'Aktif')))}
