function cashAccount(name){if(name==='Kas Tunai')return state.accounts.find(x=>x.code==='1001');if(name==='Bank')return state.accounts.find(x=>x.code==='1002');return null}
function cashBalance(name){if(name==='Petty Cash')return Number(orgV6().pettyBalance??1500000);return Number(cashAccount(name)?.balance||0)}
async function setCashBalance(name,value,patch){if(name==='Petty Cash'){patch.pettyBalance=value;return}let a=cashAccount(name);if(a){a.balance=value;await put('accounts',a)}}
function openCashTxV6(){formContext=async fd=>{let o=orgV6(),ledger=o.cashLedger||[],account=fd.get('account'),direction=fd.get('direction'),amount=Number(fd.get('amount'));if(!amount||amount<=0){toast('Jumlah transaksi harus lebih dari nol');return}let old=cashBalance(account),next=direction==='Masuk'?old+amount:old-amount;if(next<0){toast('Saldo '+account+' tidak mencukupi');return}let patch={cashLedger:[...ledger,{id:uid('cash'),date:fd.get('date'),ref:fd.get('ref'),account,direction,amount,note:fd.get('note'),createdAt:new Date().toISOString()}]};await setCashBalance(account,next,patch);await saveOrgV6(patch,'Transaksi kas disimpan');closeModal()};openModal('Transaksi Kas/Bank',formWrap(input('date','Tanggal',new Date().toISOString().slice(0,10),'date','required')+input('ref','Nomor Bukti','KB-'+Date.now().toString().slice(-6),'text','required')+select('account','Akun',['Kas Tunai','Bank','Petty Cash'])+select('direction','Jenis',['Masuk','Keluar'])+input('amount','Jumlah',0,'number','required')+textarea('note','Uraian')))}
function openCashTransferV6(target){formContext=async fd=>{let o=orgV6(),amount=Number(fd.get('amount')),ledger=o.cashLedger||[],from=fd.get('from'),to=fd.get('to');if(from===to){toast('Akun asal dan tujuan tidak boleh sama');return}if(!amount||amount<=0){toast('Jumlah transfer harus lebih dari nol');return}let fromBal=cashBalance(from),toBal=cashBalance(to);if(fromBal<amount){toast('Saldo '+from+' tidak mencukupi');return}let ref='TR-'+Date.now().toString().slice(-6),date=fd.get('date'),patch={cashLedger:[...ledger,{id:uid('cash'),date,ref,account:from,direction:'Keluar',amount,note:'Transfer ke '+to},{id:uid('cash'),date,ref,account:to,direction:'Masuk',amount,note:'Transfer dari '+from}]};await setCashBalance(from,fromBal-amount,patch);await setCashBalance(to,toBal+amount,patch);await saveOrgV6(patch,'Transfer/top-up disimpan');closeModal()};openModal('Transfer Antar Kas/Bank',formWrap(input('date','Tanggal',new Date().toISOString().slice(0,10),'date')+select('from','Dari',['Bank','Kas Tunai','Petty Cash'])+select('to','Ke',['Petty Cash','Bank','Kas Tunai'],target)+input('amount','Jumlah',0,'number','required')+textarea('note','Catatan')))}

async function init(){
  db=await openDB();
  await loadState();
  await seedIfNeeded();
  enhanceSeedData();
  persistState();
  renderMenu();renderPublic();renderCurrent();
}

init().catch(e=>{console.error(e);document.body.innerHTML='<pre style="padding:20px">Gagal membuka penyimpanan lokal: '+esc(e.message)+'</pre>'});
</script>

<script>
// --- LARAVEL 11 + POSTGRESQL 18 API INTEGRATION OVERRIDE ---
console.log('[SIM LIA v8] Connected to Laravel 11 PostgreSQL 18 Backend');

const LARAVEL_API = {
  async get(url) {
    try {
      const res = await fetch(url);
      const json = await res.json();
      return json.data || json;
    } catch(e) { console.error('API Error:', e); return []; }
  },
  async post(url, data) {
    try {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(data)
      });
      return await res.json();
    } catch(e) { console.error('API Error:', e); return { message: 'Gagal' }; }
  }
};

// Override state loading from Laravel PostgreSQL API
async function syncStateWithPostgres() {
  try {
    const [p, s, a, n, stu, cls, ld, emp, inv, pay, exp] = await Promise.all([
      LARAVEL_API.get('/api/public/programs'),
      LARAVEL_API.get('/api/public/settings'),
      LARAVEL_API.get('/api/public/achievements'),
      LARAVEL_API.get('/api/public/news'),
      LARAVEL_API.get('/api/academic/students'),
      LARAVEL_API.get('/api/academic/classes'),
      LARAVEL_API.get('/api/crm/leads'),
      LARAVEL_API.get('/api/hr/employees'),
      LARAVEL_API.get('/api/finance/invoices'),
      LARAVEL_API.get('/api/finance/payments'),
      LARAVEL_API.get('/api/finance/expenses')
    ]);

    if (p && p.length) state.programs = p;
    if (stu && stu.length) state.students = stu;
    if (cls && cls.length) state.classes = cls;
    if (ld && ld.length) state.leads = ld;
    if (emp && emp.length) state.employees = emp;
    if (inv && inv.length) state.invoices = inv;
    if (pay && pay.length) state.payments = pay;
    if (exp && exp.length) state.expenses = exp;

    console.log('[PostgreSQL 18] Successfully synced state with Laravel DB!');
    if (typeof renderCurrentView === 'function') renderCurrentView();
    if (state.view === 'admin' && typeof renderAdminPage === 'function') renderAdminPage();
  } catch(err) {
    console.error('Error syncing PostgreSQL:', err);
  }
}

// Attach sync on load and login
window.addEventListener('DOMContentLoaded', () => {
  setTimeout(syncStateWithPostgres, 300);
});

// Override public form submission to insert into PostgreSQL
const origSubmitPublicLead = window.submitPublicLead;
window.submitPublicLead = async function(e) {
  if (e) e.preventDefault();
  const name = document.getElementById('pubName')?.value;
  const phone = document.getElementById('pubPhone')?.value;
  const program = document.getElementById('pubProgram')?.value;
  const note = document.getElementById('pubNote')?.value;

  if (name && phone) {
    const res = await LARAVEL_API.post('/api/public/leads', { name, phone, program, note });
    if (typeof showToast === 'function') showToast(res.message || 'Pendaftaran berhasil dikirim ke PostgreSQL!');
    if (document.getElementById('publicForm')) document.getElementById('publicForm').reset();
    syncStateWithPostgres();
  }
};
</script>


