<script>
// --- PORTAL SISWA & ORANG TUA JS ENGINE ---
function openStudentPortal() {
  state.view = 'studentPortal';
  renderCurrentView();
  fetchStudentPortalData();
}

function switchPortalTab(tabId, btn) {
  document.querySelectorAll('#studentPortal .tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('#studentPortal .tab-panel').forEach(p => p.classList.remove('active'));
  if (btn) btn.classList.add('active');
  const target = document.getElementById('ptab-' + tabId);
  if (target) target.classList.add('active');
}

async function fetchStudentPortalData() {
  try {
    const res = await LARAVEL_API.get('/api/portal/student-profile');
    if (res && res.student) {
      document.getElementById('portalStudentName').innerText = res.student.name;
      document.getElementById('bannerStudentName').innerText = 'Selamat Datang, ' + res.student.name + '!';
      document.getElementById('portalStudentNis').innerText = 'NIS: ' + (res.student.student_no || res.student.id);
      if (res.attendance_rate) document.getElementById('portalAttendanceRate').innerText = res.attendance_rate;
      if (res.scores && res.scores.final_grade) document.getElementById('portalFinalGrade').innerText = res.scores.final_grade;
    }
  } catch(e) {
    console.error('Portal sync error:', e);
  }
}

// Override renderCurrentView to support studentPortal view
const origRenderCurrentView = window.renderCurrentView;
window.renderCurrentView = function() {
  const publicSite = document.getElementById('publicSite');
  const adminApp = document.getElementById('adminApp');
  const studentPortal = document.getElementById('studentPortal');

  if (state.view === 'public') {
    if (publicSite) publicSite.classList.remove('hidden');
    if (adminApp) adminApp.classList.add('hidden');
    if (studentPortal) studentPortal.classList.add('hidden');
  } else if (state.view === 'admin') {
    if (publicSite) publicSite.classList.add('hidden');
    if (adminApp) adminApp.classList.remove('hidden');
    if (studentPortal) studentPortal.classList.add('hidden');
  } else if (state.view === 'studentPortal') {
    if (publicSite) publicSite.classList.add('hidden');
    if (adminApp) adminApp.classList.add('hidden');
    if (studentPortal) studentPortal.classList.remove('hidden');
  }
};
</script>


<script>
// --- INNOVATION JS ENGINE ---
let quizScore = 0;

function answerQuiz(step, score) {
  quizScore += score;
  document.getElementById('q' + step).classList.add('hidden');
  
  if (step < 4) {
    document.getElementById('q' + (step + 1)).classList.remove('hidden');
    document.getElementById('quizProgress').innerText = 'Pertanyaan ' + (step + 1) + ' dari 4';
  } else {
    document.getElementById('quizProgress').innerText = 'Selesai!';
    document.getElementById('quizResult').classList.remove('hidden');
    
    let progName = 'General English for Young Learners (GEYL)';
    let progDesc = 'Skor: ' + quizScore + '/100. Disarankan untuk jenjang SD dengan fokus percakapan dasar.';
    
    if (quizScore >= 80) {
      progName = 'TOEFL & IELTS Preparation (TP)';
      progDesc = 'Skor: ' + quizScore + '/100. Kemampuan tata bahasa Anda sangat baik! Disarankan mengambil program TOEFL Prep.';
    } else if (quizScore >= 60) {
      progName = 'General English for Adults (GEA Level 2)';
      progDesc = 'Skor: ' + quizScore + '/100. Kemampuan Anda berada di tingkat menengah (Intermediate).';
    } else if (quizScore >= 40) {
      progName = 'General English for Teens (GET Level 1)';
      progDesc = 'Skor: ' + quizScore + '/100. Cocok untuk tingkat SMP/SMA dalam menguatkan fondasi bahasa Inggris.';
    }
    
    document.getElementById('resProgramName').innerText = progName;
    document.getElementById('resProgramDesc').innerText = progDesc;
  }
}

function applyQuizToForm() {
  const progSelect = document.getElementById('pubProgram');
  if (progSelect) {
    if (quizScore >= 80) progSelect.value = 'TP';
    else if (quizScore >= 60) progSelect.value = 'GEA';
    else if (quizScore >= 40) progSelect.value = 'GET';
    else progSelect.value = 'GEYL';
  }
  window.location.hash = '#kontak';
  showToast('Rekomendasi program telah diterapkan pada formulir!');
}

function calculateTuition() {
  const base = Number(document.getElementById('calcProgram').value || 1250000);
  const scheme = Number(document.getElementById('calcScheme').value || 1);
  const voucher = (document.getElementById('calcVoucher').value || '').trim().toUpperCase();

  let discount = scheme === 1 ? 50000 : 0;
  if (voucher === 'LIA2026' || voucher === 'EARLYBIRD') {
    discount += 100000;
  } else if (voucher === 'ALUMNI10') {
    discount += 150000;
  }

  const net = Math.max(0, base - discount);
  const perInstallment = Math.round(net / scheme);

  document.getElementById('calcBaseFee').innerText = 'Rp ' + base.toLocaleString('id-ID');
  document.getElementById('calcDiscount').innerText = '- Rp ' + discount.toLocaleString('id-ID');
  document.getElementById('calcTotalNet').innerText = 'Rp ' + net.toLocaleString('id-ID');
  document.getElementById('calcInstallment').innerText = 'Rp ' + perInstallment.toLocaleString('id-ID') + ' (' + scheme + 'x)';
  document.getElementById('calcSubtext').innerText = scheme === 1 ? 'Lunas 100% dengan potongan diskon.' : 'Skema angsuran ' + scheme + 'x per periode.';
}

// Initial calculation
window.addEventListener('DOMContentLoaded', () => {
  setTimeout(calculateTuition, 500);
});
</script>

